/* Finish Line: HRM (HM01) exam section. Exam-first: practice papers in the exam's format
   (20 MCQ + a case with a 4-point and a 6-point question), cards, and a theory overview on the side. */
(function(){
"use strict";
var FL = window.FL; if(!FL) return;
var esc = FL.esc;
var D = {"qs": [{"t": "brand", "q": "In signalling theory, employer branding messages primarily:", "o": ["Reduce recruitment costs automatically", "Communicate prestige, values and expected treatment to job seekers", "Guarantee employee loyalty", "Eliminate decision-making biases"], "a": 1, "w": "Signalling theory: the firm sends observable signals about qualities candidates can't see (values, prestige, how you'll be treated), reducing information asymmetry.", "src": "2025 exam", "id": "p1-1", "wn": {"0": "Branding may lower costs over time, but that's an effect, not what signalling is about. Signalling is about communicating hidden qualities.", "2": "Nothing guarantees loyalty; signals only shape expectations.", "3": "That's selection (Session 4), not branding."}}, {"t": "brand", "q": "The psychological contract perspective on employer branding highlights that:", "o": ["Recruitment adverts shape expectations about the employment deal", "Branding only affects customers, not employees", "The employer brand has no impact once the employee is hired", "Employees ignore branding once they enter the firm"], "a": 0, "w": "Psychological contract = unwritten reciprocal expectations (Schein 1980). The brand creates those expectations before people join.", "src": "2025 exam", "id": "p1-2", "wn": {"1": "Wrong: the employer brand also works on current employees (Sparrow & Otaye).", "2": "It keeps shaping the psychological contract after hiring; that's the point.", "3": "They compare the promise with reality; that's how breaches happen."}}, {"t": "brand", "q": "A common risk of employer branding is:", "o": ["Overemphasising authenticity and transparency", "Misalignment between external promises and internal employee experience", "Focusing on diversity in recruitment", "Using too many communication channels"], "a": 1, "w": "If the promise (image) doesn't match reality (identity), the psychological contract is breached: disappointment and turnover.", "src": "2025 exam", "id": "p1-3", "wn": {"0": "Authenticity is the cure, not the risk.", "2": "Diversity isn't a branding risk.", "3": "Not a risk named in class; the classic risk is the promise vs reality gap."}}, {"t": "rec", "q": "Which recruitment practice is most likely to limit diversity in the talent pool?", "o": ["Partnering with a variety of universities", "Hiring only through employee referrals", "Posting jobs on open-access job boards", "Running targeted outreach campaigns"], "a": 1, "w": "Referrals reproduce the existing network: people refer people like themselves (similar-to-me).", "src": "2025 exam", "id": "p1-4", "wn": {"0": "Widens the pool, so it increases diversity.", "2": "Open to everyone, so it increases diversity.", "3": "Usually used to reach under-represented groups."}}, {"t": "rec", "q": "A recruitment strategy focused on internal candidates:", "o": ["Is always cheaper and faster than external hiring", "Can support retention but may limit fresh ideas and innovation", "Completely eliminates selection bias", "Is incompatible with employer branding"], "a": 1, "w": "Internal: career planning, morale, easier assessment, cheaper. Downsides: stagnation, fewer new ideas, competition among employees.", "src": "2025 exam", "id": "p1-5", "wn": {"0": "'Always' is the trap: usually cheaper, not always.", "2": "Nothing eliminates bias completely; internal choices have their own biases (favouritism).", "3": "Career paths are part of a strong employer brand."}}, {"t": "sel", "q": "Which of the following is an error in selection that can bias decisions?", "o": ["Expectancy effect", "Validity effect", "Similar-to-me bias", "Performance-related bias"], "a": 2, "w": "Interviewer errors: halo/horn, stereotyping, similar-to-me, snap decisions, contrast effect, fundamental attribution error, insufficient information.", "src": "2025 exam", "id": "p1-6", "wn": {"0": "Sounds like Vroom (motivation), not a selection error from the list.", "1": "Validity is a quality of a method, not a bias.", "3": "Made-up term. The class list is halo/horn, stereotyping, similar-to-me, snap decisions, contrast, attribution error."}}, {"t": "sel", "q": "Which of the following is not a criterion for evaluating selection methods?", "o": ["Validity", "Reliability", "Legality", "Profitability"], "a": 3, "w": "Criteria: reliable, valid, generalizable, high utility, legal. Profitability isn't one.", "src": "2025 exam", "id": "p1-7", "wn": {"0": "This IS a criterion (measures what it should).", "1": "This IS a criterion (free from random error).", "2": "This IS a criterion (methods must be legal)."}}, {"t": "sel", "q": "In the context of selection methods, validity refers to:", "o": ["The degree to which a method consistently produces the same results", "The degree to which a method accurately measures what it is intended to predict (e.g. job performance)", "The legal acceptability of a method", "The cost-effectiveness of a method"], "a": 1, "w": "a) is reliability. Validity = measures what it should, all the relevant and only the relevant aspects.", "src": "2025 exam", "id": "p1-8", "wn": {"0": "That's reliability. Consistent ≠ correct.", "2": "That's legality, a separate criterion.", "3": "That's utility."}}, {"t": "pm", "q": "One of the three main business reasons companies dropped traditional appraisals was:", "o": ["To reduce HR budgets", "To make HR's role more relevant for board decisions", "To strengthen teamwork and agility", "To focus more on pay fairness"], "a": 2, "w": "Cappelli & Tavis: (1) return of people development, (2) need for agility, (3) centrality of teamwork.", "src": "2025 exam", "id": "p1-9", "wn": {"0": "Not one of Cappelli & Tavis's three reasons (people development, agility, teamwork).", "1": "Sounds strategic, but not one of the three reasons.", "3": "Pay fairness is actually a remaining challenge, not a reason."}}, {"t": "pm", "q": "A relative performance management system (e.g. forced ranking):", "o": ["Reduces bias and improves collaboration", "Classifies employees into categories compared to peers", "Focuses on long-term developmental feedback", "Is preferred in team-based organisations"], "a": 1, "w": "Relative standards compare people with each other: simple ranking, paired comparison, forced distribution.", "src": "2025 exam", "id": "p1-10", "wn": {"0": "The opposite: forced ranking hurts collaboration.", "2": "That's the Cappelli & Tavis alternative.", "3": "Team-based firms dropped it because it kills teamwork."}}, {"t": "pm", "q": "Which is a potential drawback of forced distribution systems?", "o": ["They motivate everyone equally", "They tend to reduce collaboration and morale", "They are cost-free to implement", "They avoid all bias"], "a": 1, "w": "Drawbacks: horse-trading, infighting (no collaboration), short-termism. Barankay: performance fell when people were rated relative to others.", "src": "2025 exam", "id": "p1-11", "wn": {"0": "Ranking creates winners and losers by design.", "2": "Managers spend lots of time horse-trading; that's a cost.", "3": "Rankings are still subjective and biased."}}, {"t": "pm", "q": "A shift from accountability to learning in performance management implies:", "o": ["Focus on sanctioning low performers", "Emphasis on continuous feedback and development", "Avoiding any evaluation at all", "Eliminating performance conversations"], "a": 1, "w": "Cappelli & Tavis: frequent, informal check-ins following the natural cycle of work, focused on development.", "src": "2025 exam", "id": "p1-12", "wn": {"0": "That's the accountability side, the old model.", "2": "Firms still evaluate, just more often and informally.", "3": "The opposite: more frequent conversations."}}, {"t": "comp", "q": "According to equity theory, employees evaluate fairness by comparing:", "o": ["Pay levels across countries", "Their input/output ratio with referent others", "Their bonus size to last year's profits", "HR policies across industries"], "a": 1, "w": "Adams (1963): inputs (effort, education) vs outcomes (pay, raises), compared with a referent (self/other, inside/outside).", "src": "2025 exam", "id": "p1-13", "wn": {"0": "Too broad; equity is about your ratio vs a referent.", "2": "That's not a comparison with other people.", "3": "Not inputs vs outcomes."}}, {"t": "comp", "q": "Which of the following is an intended effect of performance-related pay (PRP)?", "o": ["Aligning employee efforts with organisational goals", "Undermining cooperation", "Increasing turnover", "Encouraging short-termism"], "a": 0, "w": "The others are side effects (unintended), not intended effects.", "src": "2025 exam", "id": "p1-14", "wn": {"1": "A side effect (unintended), not an intended effect.", "2": "Unintended side effect.", "3": "Unintended side effect."}}, {"t": "comp", "q": "Paying employees more because their jobs require higher responsibility and skills reflects which principle?", "o": ["Internal consistency", "External competitiveness", "Agency alignment", "Equity of effort"], "a": 0, "w": "Internal consistency: job evaluation and pay grades inside the firm. External competitiveness: salary surveys, market.", "src": "2025 exam", "id": "p1-15", "wn": {"1": "That's paying vs the MARKET (salary surveys). Here the comparison is between jobs inside the firm.", "2": "Agency theory isn't covered as a pay principle; it's the exam's distractor.", "3": "Not a class principle. It sounds like Adams' equity theory, but that's about people comparing their input/output ratio, not about valuing jobs by responsibility."}}, {"t": "sel", "q": "Which criterion would not be valid to select a laboratory technician in a medical testing facility?", "o": ["Attention to detail and accuracy", "Strong laboratory safety awareness", "Outstanding team-leadership and strategic management", "Adherence to ethical standards in handling data"], "a": 2, "w": "Validity = only job-relevant criteria. Strategic leadership isn't part of a technician's job (it would be 'contamination').", "src": "2025 exam", "id": "p1-16", "wn": {"0": "Job-relevant for a lab technician, so a valid criterion.", "1": "Job-relevant, so a valid criterion.", "3": "Job-relevant, so a valid criterion."}}, {"t": "comp", "q": "Two senior managers have equally complex roles, but one manages several high-risk, high-impact projects and the other a single stable project. Which approach is most defensible for internal consistency and strategic reward?", "o": ["Equal pay to signal equity", "Higher pay for the manager with greater scope and value of responsibility", "External benchmarking only", "Identical base pay, bonus only on company profit"], "a": 1, "w": "Internal consistency: pay reflects the job's value (responsibility, scope, impact) relative to other jobs.", "src": "2025 exam", "id": "p1-17", "wn": {"0": "Equal pay for unequal responsibility actually breaks internal consistency, and the bigger-scope manager would feel unfairly treated (Adams).", "2": "Market data alone ignores the difference in job value inside the firm.", "3": "Same problem: base pay ignores the different scope, and a profit-only bonus doesn't reward the extra responsibility."}}, {"t": "brand", "q": "A tech firm with high engineer turnover runs social media campaigns as an 'innovative, employee-centric' employer, but exit interviews cite limited career progression and inconsistent leadership. Best action?", "o": ["More marketing on professional networks", "Develop internal talent and leadership initiatives so the experience matches the brand promise", "Higher sign-on bonuses and referral incentives", "Rebrand around short-term perks"], "a": 1, "w": "Fix identity, not image: align the employee experience with the promise (psychological contract; EVP growth and development).", "src": "2025 exam", "id": "p1-18", "wn": {"0": "More advertising widens the gap between image and reality.", "2": "Material offerings are easy to copy and don't fix why engineers leave.", "3": "Same: perks don't fix career progression or leadership."}}, {"t": "comp", "q": "Expectancy theory: an employee believes no matter how well they perform, the manager won't grant the promised bonus. What is lacking?", "o": ["Expectancy", "Valence", "Instrumentality", "Self-efficacy"], "a": 2, "w": "Vroom: Expectancy = my effort leads to performance; Instrumentality = performance leads to reward; Valence = value of the reward. Here performance won't lead to reward.", "src": "2025 exam", "id": "p1-19", "wn": {"0": "Expectancy = 'my effort leads to performance'. Here they CAN perform; the problem is the reward.", "1": "Valence = 'I value the reward'. They'd want the bonus; they just don't believe they'll get it.", "3": "Not one of Vroom's three components."}}, {"t": "sel", "q": "An AI screening tool consistently ranks some demographic groups lower despite equal qualifications. Most evidence-based and ethical response?", "o": ["Retrain on historical data for consistency", "Replace AI with human screening to eliminate bias completely", "Audit validity and bias, adjust inputs, keep human judgment in final decisions", "Accept the output as objective"], "a": 2, "w": "Session 4: AI learns from past data (Amazon 2018); audit for bias, ask for explainability, human-in-the-loop. Humans aren't bias-free either, so b) is wrong.", "src": "2025 exam", "id": "p1-20", "wn": {"0": "Historical data is where the bias comes from (Amazon).", "1": "Humans are biased too; 'completely' is the trap.", "3": "Consistent isn't the same as fair or valid."}}, {"id": "n1", "t": "intro", "q": "HRM is best defined as:", "o": ["Compliance with labour law", "The administration of payroll and contracts", "The recruitment of top talent only", "The policies, practices and systems that influence employees' behaviour, attitudes and performance"], "a": 3, "w": "Noe et al.: policies, practices and systems that influence behaviour, attitudes and performance.", "wn": {}}, {"id": "n2", "t": "intro", "q": "A 'high-commitment HR system' is an example of:", "o": ["A single HR practice", "An HR policy", "An HR system: a bundle of consistent, reinforcing practices", "A labour law requirement"], "a": 2, "w": "Lepak et al. 2006: a policy is the commitment (e.g. to PFP), practices are the specific actions, and a system is a bundle of practices.", "wn": {"0": "One practice = one action (e.g. 360°). The question says a bundle.", "1": "A policy is the intention (e.g. 'we're committed to high performance'). A bundle of practices is a system."}}, {"id": "n3", "t": "intro", "q": "According to the resource-based view, human resources create sustained competitive advantage when they are:", "o": ["Standardised across the industry", "Cheap and flexible", "Easy to replace", "Valuable, rare, inimitable and non-substitutable"], "a": 3, "w": "Barney (1991); Barney & Wright (1998): VRIN.", "wn": {}}, {"id": "n4", "t": "intro", "q": "The 'contingency' approach to HRM argues that:", "o": ["There is one best way: copy best practices", "HR has no effect on performance", "HR should follow the US model", "HR must fit the context: organisation, industry, country"], "a": 3, "w": "Universalism = one best way, best practices; contingency = context matters (Festing 2012). Contingency is the widely accepted view.", "wn": {"0": "That's the universalist view, the opposite of contingency."}}, {"id": "n5", "t": "intro", "q": "In the HRM–performance link, signalling theory (Bowen & Ostroff 2004) suggests that HR practices:", "o": ["Only affect costs", "Matter only for recruitment", "Are invisible to employees", "Send messages to employees about which behaviours and competencies are valued, creating a climate"], "a": 3, "w": "HR continuously sends messages that shape employees' perception of what the organisation values (e.g. Netflix 'Freedom & Responsibility').", "wn": {}}, {"id": "n6", "t": "intro", "q": "Strategic HRM (Wright & McMahan 1992) is:", "o": ["Annual appraisal", "The pattern of planned HR deployments and activities intended to enable an organisation to achieve its goals", "Outsourcing HR", "The HR department's budget"], "a": 1, "w": "Definition used in class.", "wn": {}}, {"id": "n7", "t": "brand", "q": "Employer brand is best described as:", "o": ["The CEO's personal brand", "The salary level offered", "The company's product logo", "The employer's reputation plus its value proposition for employees"], "a": 3, "w": "Employer brand = reputation as an employer + value proposition for employees; promoted to become an 'employer of choice'.", "wn": {}}, {"id": "n8", "t": "brand", "q": "Who defined the psychological contract as 'a set of unwritten reciprocal expectations between an individual employee and the organisation'?", "o": ["Becker", "Herzberg", "Vroom", "Schein (1980)"], "a": 3, "w": "Schein 1980; Sparrow & Cooper (1998) added that expectations evolve over time and concern social and emotional aspects.", "wn": {"0": "Becker = human capital theory (Session 3).", "1": "Herzberg = hygiene factors vs motivators.", "2": "Vroom = expectancy theory (Session 5)."}}, {"id": "n9", "t": "brand", "q": "In the six-step employer branding model, step 1 'Who am I?' contrasts:", "o": ["Customers and competitors", "Identity (who I am) and image (what others see)", "Pay and benefits", "Internal and external recruitment"], "a": 1, "w": "Steps: 1 who am I, 2 customers, 3 competitors, 4 distinctive EVP, 5 create and communicate brand, 6 evaluate impact.", "wn": {"0": "Those are steps 2 and 3 of the model, not step 1."}}, {"id": "n10", "t": "brand", "q": "Mortensen & Edmondson's four EVP factors are:", "o": ["Recruitment, selection, appraisal, pay", "Material offerings; development and growth; connection and community; meaning and purpose", "Image, identity, channels, KPIs", "Pay, perks, location, flexibility"], "a": 1, "w": "The EVP is a system of four interrelated factors.", "wn": {"2": "Those are terms from the six-step branding model, not the EVP.", "3": "These are all one factor: material offerings."}}, {"id": "n11", "t": "brand", "q": "According to Mortensen & Edmondson, which EVP factors are experienced in the long term?", "o": ["Growth and development; meaning and purpose", "Connection and community only", "Only material offerings", "Material offerings and connection"], "a": 0, "w": "Short term: material offerings, connection and community. Long term: growth, meaning and purpose. Individual: material, growth. Collective: connection, purpose.", "wn": {"1": "Short-term and collective.", "3": "Both are short-term factors."}}, {"id": "n12", "t": "brand", "q": "Why can relying mainly on pay, perks and flexibility create a 'race to the bottom'?", "o": ["They are too cheap", "Employees don't value pay", "They are easy for competitors to imitate and their retention effect is the least enduring", "They are illegal"], "a": 2, "w": "Material offerings are the easiest lever but easiest to copy: firms outbid each other.", "wn": {}}, {"id": "n13", "t": "brand", "q": "At UNICEF, what went wrong with the EVP?", "o": ["Pay was too high", "Promoting its powerful purpose in isolation created a toxic culture", "It allowed remote work", "It had no purpose"], "a": 1, "w": "Even purpose, used alone, can backfire: the EVP must be a system.", "wn": {}}, {"id": "n14", "t": "brand", "q": "Best Buy's turnaround under Hubert Joly put which EVP element first?", "o": ["Meaning and purpose ('enriching customers' lives through technology')", "Material offerings", "Forced ranking", "Remote work"], "a": 0, "w": "Profit treated as an outcome of a noble purpose; WD-40 asked employees to decide where to work using company values.", "wn": {"1": "Joly did improve perks, but he put purpose FIRST."}}, {"id": "n15", "t": "brand", "q": "Mortensen & Edmondson's three steps for leaders are:", "o": ["Cut costs, outsource, automate", "Advertise, recruit, select", "Assess what you have and what employees need; change the conversation; ...build an integrated EVP", "Hire, pay, fire"], "a": 2, "w": "1 assess supply and demand, 2 change the conversation (explain why), 3 address the factors holistically.", "wn": {}}, {"id": "n16", "t": "brand", "q": "In the remote-work example, why did engagement fall at the software firm that granted remote work?", "o": ["Too many meetings", "Pay dropped", "Loss of connection and belonging", "Bad managers"], "a": 2, "w": "Giving one material offering hurt connection and community: factors must be managed together.", "wn": {}}, {"id": "n17", "t": "brand", "q": "L'Oréal's Brandstorm competition is an example of which employer branding step?", "o": ["Create a unique brand and communicate it (through universities)", "Who am I?", "Know your competitors", "Evaluate impact"], "a": 0, "w": "Channels: universities, job sites, social networks, mass media.", "wn": {"1": "Step 1 (identity vs image).", "3": "Step 6. Brandstorm is about communicating the brand (step 5)."}}, {"id": "n18", "t": "brand", "q": "Common employer brand KPIs (Brandon Hall) fall into:", "o": ["Salary benchmarks", "Volume and exposure, baseline measures, engagement", "Absenteeism only", "Profit, revenue, EBITDA"], "a": 1, "w": "Plus external recognition (rankings, awards).", "wn": {}}, {"id": "n19", "t": "brand", "q": "Schein's career anchors (Career Orientations Inventory) help to:", "o": ["Rank employees", "Calculate turnover", "Understand what individuals value in a career, e.g. security, autonomy, technical competence", "Set pay grades"], "a": 2, "w": "Used in the Session 2 exercise; links to what candidates expect (psychological contract).", "wn": {}}, {"id": "n20", "t": "rec", "q": "Which is an advantage of external recruitment?", "o": ["New ideas and more opportunity for innovation", "Lower cost", "Applicants already know the firm", "Better morale of existing staff"], "a": 0, "w": "External: right skills, new ideas. But costly and riskier.", "wn": {"1": "Lower cost is an advantage of INTERNAL recruitment.", "2": "Internal advantage.", "3": "Internal advantage (promotions show a career path)."}}, {"id": "n21", "t": "rec", "q": "Human capital (Becker 1964) is:", "o": ["Share capital", "The knowledge, information, ideas, skills and health of individuals", "The firm's machines", "The HR budget"], "a": 1, "w": "Becker distinguishes general and firm-specific human capital.", "wn": {}}, {"id": "n22", "t": "rec", "q": "Which type of human capital is the most portable to another firm?", "o": ["Industry-specific when moving industry", "General (management) skills", "Relationship", "Company-specific"], "a": 1, "w": "Groysberg, McLean & Nohria (2006): from least to most portable: company-specific, relationship, industry, strategic, general.", "wn": {"0": "Doesn't travel across industries.", "2": "Depends on the team and clients you leave behind.", "3": "LEAST portable: stays with the firm."}}, {"id": "n23", "t": "rec", "q": "'Hard nonportability' refers to:", "o": ["Skills to produce goods no other firm sells", "Mastery of a firm's computerised systems and idiosyncratic platforms", "Personality", "Unique firm culture and HR practices"], "a": 1, "w": "Soft = culture and HR practices; hard = systems and data; product-based = products no one else sells.", "wn": {"0": "That's product-based nonportability.", "3": "That's SOFT nonportability."}}, {"id": "n24", "t": "rec", "q": "Groysberg, Nanda & Nohria (2004) found that when star analysts move to a new firm:", "o": ["Their performance declines, and so does their new team's effectiveness", "They stay for decades", "Nothing changes", "Their performance rises"], "a": 0, "w": "Company-specific skills matter: cultivate talent from within and retain your stars.", "wn": {}}, {"id": "n25", "t": "rec", "q": "In 'Recruitment of a Star', the dilemma faced by Stephen Connor is:", "o": ["How to fire Rina Shea", "Whom to hire (or promote) to replace star analyst Peter Thompson, who left for a competitor", "Whether to use AI", "Whether to cut salaries"], "a": 1, "w": "Candidates: Hughes, Baum, Meetha, Horkum, or develop Rina Shea from within: portability of human capital and fit.", "wn": {}}, {"id": "n26", "t": "rec", "q": "Choosing temporary rather than permanent recruitment is mainly based on:", "o": ["The CEO's preference", "The HR forecast of how long the shortage will last", "The employer brand", "Candidates' age"], "a": 1, "w": "Temporary staff are less costly and available via agencies.", "wn": {}}, {"id": "n27", "t": "rec", "q": "Which is a disadvantage of internal recruitment?", "o": ["High advertising cost", "Business stagnation and promoted staff may lack potential for senior roles", "High risk of a bad hire from outside", "Applicants don't know the firm"], "a": 1, "w": "Plus competition among employees and low morale for those not promoted.", "wn": {}}, {"id": "n28", "t": "sel", "q": "Which interview format is the most reliable and valid?", "o": ["Structured (predetermined questions)", "Non-directive", "Unplanned chat", "Stress interview"], "a": 0, "w": "Non-directive interviews tend to be unreliable and can lead to irrelevant or illegal questions.", "wn": {}}, {"id": "n29", "t": "sel", "q": "'Tell me about a time you handled a difficult client' is a:", "o": ["Behaviour description interview question", "Non-directive question", "Personality test", "Situational interview question"], "a": 0, "w": "BDI asks about past behaviour (past behaviour predicts future). Situational asks 'what would you do if…'.", "wn": {"3": "Situational = hypothetical future ('what WOULD you do if…'). 'Tell me about a time' is past behaviour."}}, {"id": "n30", "t": "sel", "q": "Reliability is:", "o": ["Cost", "Measuring all relevant aspects of performance", "Legal acceptability", "The degree to which a measure is free from random error"], "a": 3, "w": "Reliability is necessary but not sufficient for validity.", "wn": {"1": "That's validity (no deficiency)."}}, {"id": "n31", "t": "sel", "q": "Which statement is correct?", "o": ["Reliability is necessary but not sufficient for validity", "Utility is independent of validity", "Reliable methods are always valid", "Validity is necessary but not sufficient for reliability"], "a": 0, "w": "The order is reliability, validity, generalizability, utility: each is necessary but not sufficient for the next.", "wn": {"2": "A consistent scale can be consistently wrong.", "3": "Reversed. Reliability comes first: a method must be consistent before it can be valid."}}, {"id": "n32", "t": "sel", "q": "In a multiple-hurdle selection model:", "o": ["Candidates are eliminated at each stage", "There are no tests", "Everyone goes through all stages", "A high score on one test compensates for a low one"], "a": 0, "w": "Compensatory model: all go through all stages, strengths offset weaknesses.", "wn": {"2": "Also the compensatory model.", "3": "That's the compensatory model."}}, {"id": "n33", "t": "sel", "q": "The halo effect means:", "o": ["Preferring people like oneself", "Comparing a candidate with the previous one", "Judging a candidate positively overall because of one strong trait", "Deciding in the first minutes"], "a": 2, "w": "Contrast effect = compared with previous candidate; similar-to-me = preferring people like you; snap decisions.", "wn": {"0": "Similar-to-me bias.", "1": "Contrast effect.", "3": "Snap decision."}}, {"id": "n34", "t": "sel", "q": "Which selection method is valid and relatively low cost but carries legal risk?", "o": ["Polygraph", "Medical exams before hiring", "Cognitive ability tests", "Graphology"], "a": 2, "w": "Cognitive tests measure verbal, quantitative and reasoning skills.", "wn": {}}, {"id": "n35", "t": "sel", "q": "Amazon scrapped its AI CV-screening tool (2018) because:", "o": ["Trained on 10 years of past hires, it learned to penalise women", "Candidates disliked it", "It was too slow", "It cost too much"], "a": 0, "w": "Key messages: AI for mechanical tasks, humans for cognitive ones; audit for bias; human-in-the-loop.", "wn": {}}, {"id": "n36", "t": "sel", "q": "Thomas & Ely (1996) describe three diversity paradigms. Which is the most advanced?", "o": ["Access and legitimacy (differentiation)", "Affirmative quotas", "Learning and effectiveness (integration)", "Discrimination and fairness (assimilation)"], "a": 2, "w": "Learning & effectiveness integrates differences into how work is done; access & legitimacy uses diverse staff to reach diverse markets.", "wn": {"0": "The middle paradigm: diverse staff to reach diverse markets.", "3": "The first, least advanced paradigm: 'treat everyone the same, blend in'."}}, {"id": "n37", "t": "sel", "q": "Diversity researchers use signalling theory to explain that a diverse workforce:", "o": ["Replaces selection tests", "Sends observable signals about the firm's values to candidates, customers and investors", "Has no external effect", "Lowers costs"], "a": 1, "w": "'Investing' in diversity is an observable signal that can attract candidates, customers and investors.", "wn": {}}, {"id": "n38", "t": "sel", "q": "Austin & Pisano (SAP, HPE) argue that to hire neurodiverse talent, firms should:", "o": ["Use cognitive tests only", "Avoid adjustments", "Use non-interview-based assessments and adapt the process", "Rely on structured interviews"], "a": 2, "w": "Many neurodiverse people don't interview well; SAP placed over 100 programme employees in 18 roles.", "wn": {"3": "Interviews of any kind are what screen neurodiverse talent out."}}, {"id": "n39", "t": "sel", "q": "Ingram's 'forgotten dimension of diversity' is:", "o": ["Age", "Social class / socioeconomic background", "Gender", "Nationality"], "a": 1, "w": "Ingram (2021): class background is often ignored in diversity efforts.", "wn": {}}, {"id": "n40", "t": "sel", "q": "Which tool aims to reduce discrimination in selection?", "o": ["Anonymous CVs", "Unstructured interviews", "Photo requests", "Referral-only hiring"], "a": 0, "w": "Also: selection tests without CV, training for recruiters.", "wn": {}}, {"id": "n41", "t": "sel", "q": "A recruiter's two classic metrics, which AI promises to improve, are:", "o": ["Turnover and absenteeism", "Cost and headcount", "Salary and bonus", "Time to hire and quality of hire"], "a": 3, "w": "Session 4 (AI in recruitment).", "wn": {}}, {"id": "n42", "t": "comp", "q": "Herzberg's hygiene factors (e.g. pay, supervision, policies):", "o": ["Prevent dissatisfaction when adequate but don't create satisfaction", "Are irrelevant", "Create satisfaction when present", "Are the main motivators"], "a": 0, "w": "Motivators (advancement, recognition, responsibility) create satisfaction; satisfaction and dissatisfaction are separate scales.", "wn": {"2": "That's what MOTIVATORS do.", "3": "Pay is hygiene, not a motivator, in Herzberg."}}, {"id": "n43", "t": "comp", "q": "In Vroom's expectancy theory, 'valence' is:", "o": ["Belief that effort leads to performance", "How much the person values the reward", "Belief that performance leads to reward", "Fairness compared with others"], "a": 1, "w": "Motivation needs all three: expectancy × instrumentality × valence.", "wn": {"0": "That's expectancy.", "2": "That's instrumentality.", "3": "That's Adams' equity theory, not Vroom."}}, {"id": "n44", "t": "comp", "q": "An employee who feels underpaid relative to a colleague, according to equity theory, may:", "o": ["Change inputs, change outcomes, distort perceptions, choose another referent, or leave", "Ignore it", "Always work harder", "Only ask for a raise"], "a": 0, "w": "Six reactions in the slides.", "wn": {}}, {"id": "n45", "t": "comp", "q": "Achieving external competitiveness requires:", "o": ["Profit sharing", "Job evaluation and pay grades", "Forced ranking", "Salary surveys, a pay policy and pay rates vs the market"], "a": 3, "w": "Job evaluation and grades = internal consistency.", "wn": {"1": "That's internal consistency."}}, {"id": "n46", "t": "comp", "q": "Gainsharing:", "o": ["Gives stock options to executives", "Measures productivity improvements and shares part of each gain with employees", "Pays per piece", "Pays a share of company profits"], "a": 1, "w": "Works with information sharing, management commitment, fair standards, employee involvement.", "wn": {"3": "That's profit sharing (organisational level). Gainsharing shares productivity gains of a group."}}, {"id": "n47", "t": "comp", "q": "Compared with individual merit pay, team pay:", "o": ["Creates internal competition", "Encourages withholding information", "Is incorporated in base salary", "Rewards cooperation and information sharing and isn't built into base pay"], "a": 3, "w": "Thompson (1995).", "wn": {"0": "Individual merit pay again.", "1": "That's INDIVIDUAL merit pay.", "2": "Merit pay is; team pay isn't."}}, {"id": "n48", "t": "comp", "q": "Sayre et al. (2026) experiments show the main harm of pay-for-performance comes from:", "o": ["PFP itself", "Low average pay", "Team bonuses", "Pay uncertainty: financial insecurity leads to tunnel vision, longer hours, neglected rest"], "a": 3, "w": "Same average pay; people with uncertain pay worked longer, felt more stressed and preferred certain pay.", "wn": {"0": "Sayre's key point: it's NOT PFP itself, it's the uncertainty.", "1": "Average pay was the same in both groups."}}, {"id": "n49", "t": "comp", "q": "Which is a recommendation from Sayre et al. to build better PFP plans?", "o": ["Raise PFP to 60% of pay", "Make bonuses unpredictable", "Write clear rules, smooth uncertain income, alleviate financial insecurity", "Remove base pay"], "a": 2, "w": "Adobe (clear expectations), Amazon/Boeing (smooth), Costco/Target (raise base pay, cut PFP from 40% to 20%).", "wn": {}}, {"id": "n50", "t": "comp", "q": "Profit sharing and stock ownership are examples of:", "o": ["Group incentives", "Organisational incentives", "Individual incentives", "Non-financial rewards"], "a": 1, "w": "Individual: piecework, merit pay, bonuses, commissions. Group: gainsharing, team awards.", "wn": {"0": "Gainsharing, team awards.", "2": "Piecework, merit pay, commissions."}}, {"id": "n51", "t": "comp", "q": "Learning, a job well done and interest in the job are:", "o": ["Intrinsic rewards", "Indirect pay", "Benefits", "Extrinsic financial rewards"], "a": 0, "w": "Total reward = intrinsic + extrinsic (financial direct/indirect and non-financial).", "wn": {}}, {"id": "n52", "t": "comp", "q": "Moving from input-based to output-based pay mainly risks:", "o": ["Lower effort", "Paying for time", "Good workers leaving", "Defining output: quantity vs quality"], "a": 3, "w": "Output-based pay: good workers stay, bad ones leave, more effort, but what counts as output?", "wn": {}}, {"id": "n53", "t": "comp", "q": "'Contingency and contiguity' in rewards means:", "o": ["Rewards should be secret", "Pay is random", "Pay depends on seniority", "Rewards must clearly follow the behaviour, as soon as possible"], "a": 3, "w": "Employees must see a clear link: performance management and objective setting are essential.", "wn": {}}, {"id": "n54", "t": "comp", "q": "In the 'Name Your Price' case, the main lesson is about:", "o": ["Always asking for the maximum", "Refusing the offer", "Ignoring the market", "Setting your own pay creates questions of trust, fairness to colleagues and incentives"], "a": 3, "w": "Monroe must propose his own pay to Jim: trust game, equity with others, signalling.", "wn": {}}, {"id": "n55", "t": "pm", "q": "The four purposes of performance management are:", "o": ["Planning, budgeting, auditing, reporting", "Strategic, administrative, informational, developmental", "Legal, financial, social, technical", "Hiring, firing, paying, training"], "a": 1, "w": "The main purpose shapes the design of the system.", "wn": {}}, {"id": "n56", "t": "pm", "q": "An appraisal that rates a football player on singing ability shows:", "o": ["Specificity", "Reliability", "Contamination", "Deficiency"], "a": 2, "w": "Contamination = irrelevant information gathered; deficiency = relevant information not gathered.", "wn": {"3": "Deficiency = missing something relevant (e.g. not measuring his passing). Singing is extra and irrelevant = contamination."}}, {"id": "n57", "t": "pm", "q": "Procedural justice in performance management concerns:", "o": ["Pay levels", "Market comparison", "The fairness of the procedures used to decide the ratings", "The rating received relative to work done"], "a": 2, "w": "Distributive justice = fairness of the outcome. Strengthen procedural justice: clear criteria upfront, entitled evaluator, voice.", "wn": {"3": "That's distributive justice (the outcome)."}}, {"id": "n58", "t": "pm", "q": "Inter-rater reliability means:", "o": ["Different evaluators rate the same employee consistently", "The measure is specific", "The same measure gives similar results over time", "The measure is legal"], "a": 0, "w": "Test-retest reliability = consistency over time.", "wn": {"2": "That's test-retest reliability."}}, {"id": "n59", "t": "pm", "q": "With paired comparison, how many comparisons are needed for 15 employees?", "o": ["105", "15", "225", "30"], "a": 0, "w": "N(N−1)/2 = 15 × 14 / 2 = 105.", "wn": {"2": "That's 15×15. The formula is N(N−1)/2 = 15×14/2 = 105.", "3": "That's 15×2. Use N(N−1)/2."}}, {"id": "n60", "t": "pm", "q": "GE's 'vitality curve' under Jack Welch:", "o": ["Rewarded everyone equally", "Abolished appraisals", "Ranked staff and removed the bottom 10% each year (20-70-10)", "Used only self-assessment"], "a": 2, "w": "A, B, C players; development reserved for A players. None of the pioneers still uses it.", "wn": {}}, {"id": "n61", "t": "pm", "q": "BARS (behaviourally anchored rating scales):", "o": ["Compare employees with each other", "Are a forced ranking", "Measure only results", "Combine critical incidents and graphic rating scales with examples of actual behaviour"], "a": 3, "w": "Absolute standards for behaviours: critical incidents, BARS, 360°.", "wn": {"0": "That's relative methods (ranking). BARS is absolute."}}, {"id": "n62", "t": "pm", "q": "Management by objectives (MBO) emphasises:", "o": ["Means over ends", "Personality traits", "Ends over means: specific, participatively set, SMART goals with feedback", "Peer ranking"], "a": 2, "w": "Measures results.", "wn": {"0": "Reversed: MBO is about ends (results)."}}, {"id": "n63", "t": "pm", "q": "According to Cappelli & Tavis, which is a challenge that persists after dropping annual reviews?", "o": ["There are none", "Aligning individual and company goals, rewarding performance, identifying poor performers, avoiding legal trouble", "Employees want more rankings", "Too much teamwork"], "a": 1, "w": "Some firms try a 'third way': multiple ratings several times a year.", "wn": {}}, {"id": "n64", "t": "pm", "q": "Which company did Cappelli & Tavis cite as an early adopter that dropped annual reviews in 2002?", "o": ["Amazon", "GE", "Colorcon", "Enron"], "a": 2, "w": "Instant feedback tied to goals and small weekly bonuses. Later: Adobe, Deloitte, Accenture, PwC, Gap, even GE ('touchpoints').", "wn": {"1": "GE was a pioneer of forced ranking; it only dropped reviews later."}}, {"id": "n65", "t": "pm", "q": "In the Rob Parson at Morgan Stanley case, the core tension is:", "o": ["Outstanding results vs poor teamwork and behaviour under a new 360° 'One-Firm' culture", "Too little feedback data", "Low revenues", "Legal problems with clients"], "a": 0, "w": "Nasr must decide on the MD promotion, write the evaluation and give feedback so Parson stays and improves.", "wn": {}}, {"id": "n66", "t": "pm", "q": "In Rob Parson's 360° data, which pattern stands out?", "o": ["Colleagues rated him lowest overall", "Low scores on adherence to firm policies and team player skills from superiors, despite strong market results", "Everyone rated him highly on policies", "He scored lowest on market knowledge"], "a": 1, "w": "Superiors: policies 2.0, team skills 2.5; market knowledge 4.0–4.5. Overall 3.5 (superiors) vs 2.8.", "wn": {}}, {"id": "n67", "t": "pm", "q": "An argument AGAINST promoting Rob Parson is:", "o": ["His clients love him", "He is likely to leave", "He was implicitly promised the promotion", "MDs are 'standard bearers' of the new culture; promoting him sends the wrong signal"], "a": 3, "w": "Signalling theory again: promotions tell everyone what's valued.", "wn": {"0": "Argument FOR.", "1": "Argument FOR (retention).", "2": "That's an argument FOR promoting him."}}, {"id": "n68", "t": "pm", "q": "The 'third way' in performance management means:", "o": ["Multiple ratings several times a year to encourage growth", "No feedback at all", "Annual forced ranking", "Peer review only"], "a": 0, "w": "Cappelli & Tavis: for firms that struggle without any ratings.", "wn": {}}, {"id": "n69", "t": "pm", "q": "If an employee fails goals because the person isn't suited to the job, the slides recommend:", "o": ["Out the door immediately", "Train or reassign", "Discipline", "Coach"], "a": 1, "w": "If it's a mismatch, train or reassign; if unwilling, discipline; if obstacles, coach; if they refuse help, out the door.", "wn": {"2": "Discipline is for when the person is unwilling.", "3": "Coach is for when obstacles block performance."}}, {"id": "n70", "t": "well", "q": "Warr's vitamin model distinguishes 'AD' factors from 'CE' factors. AD factors are those where:", "o": ["Too much or too little are both bad (e.g. control, variety, externally generated goals)", "Physical security only", "Too little is bad, but more is always fine", "Only money matters"], "a": 0, "w": "AD: opportunity for control, interpersonal contact, skills use, external goals, variety, clarity. CE (too little is bad): money, physical security, valued social position.", "wn": {"2": "That describes CE vitamins (money, security)."}}, {"id": "n71", "t": "well", "q": "Cooper & Cartwright's primary interventions aim to:", "o": ["Reduce or eliminate stressors (job design, decision making, selection)", "Change perception of stress through training", "Offer gym memberships", "Rehabilitate employees under strain"], "a": 0, "w": "Secondary = stress management (training, time management); tertiary = rehabilitation (employee assistance programmes).", "wn": {"1": "Secondary intervention.", "3": "Tertiary intervention."}}, {"id": "n72", "t": "well", "q": "According to Gallup 2025, the share of employees engaged at work globally is about:", "o": ["50%", "21%", "75%", "5%"], "a": 1, "w": "Down from 23% in 2023; 15% actively disengaged.", "wn": {}}, {"id": "n73", "t": "well", "q": "The three dimensions of wellbeing at work are:", "o": ["Short-term, long-term, collective", "Pay, perks, promotion", "Mind, body, money", "Psychological, physical, social"], "a": 3, "w": "Warr 1987; Grant 2007.", "wn": {}}, {"id": "n74", "t": "intro", "q": "Boxall & Purcell (2003) define HRM as:", "o": ["Labour law compliance", "Recruitment only", "Payroll administration", "All management decisions and activities that affect the nature of the relationship between the organisation and its employees"], "a": 3, "w": "Succi Session 1. Noe et al. add: policies, practices and systems that influence behaviour, attitudes and performance.", "wn": {}}, {"id": "n75", "t": "intro", "q": "Ulrich (1997) describes the shift of the HR function:", "o": ["From staff support to business partner, enabling strategy execution", "From business partner to staff support", "From line managers to HR specialists", "From strategy to administration"], "a": 0, "w": "HR's key strategic challenges: accountability, motivation, direction, leadership and values, capabilities, monitoring.", "wn": {"1": "Reversed direction."}}, {"id": "n76", "t": "intro", "q": "Compared with traditional personnel management, strategic HRM is:", "o": ["Short-term, reactive, focused on compliance and cost minimisation", "Bureaucratic and top-down", "Long-term, proactive, based on commitment, treating people as an investment and competitive advantage", "Run only by HR specialists"], "a": 2, "w": "Traditional = specialists, compliance, reactive, cost minimisation. Strategic = integrated in line management, commitment, long-term, investment.", "wn": {"0": "That describes TRADITIONAL personnel management."}}, {"id": "n77", "t": "intro", "q": "In Barney's VRIO framework, 'O' stands for:", "o": ["Output", "Organisation: the firm is structured to capture the value of the resource", "Ownership", "Opportunity"], "a": 1, "w": "Valuable, Rare, (imperfectly) Imitable, supported by the Organisation (or non-substitutable, Wright et al. 1994).", "wn": {}}, {"id": "n78", "t": "intro", "q": "According to Barney (1991), which three types of resources can create competitive advantage?", "o": ["Skills, pay and culture", "Cash, brand and patents", "Land, labour and capital", "Physical, organisational and human capital"], "a": 3, "w": "Organisational capital includes structure, coordination and HR practices; human capital includes skills and intelligence.", "wn": {}}, {"id": "n79", "t": "intro", "q": "A deeply embedded organisational culture that can't be replicated mainly satisfies which VRIO criterion?", "o": ["Inimitable", "Valuable", "Organised", "Rare"], "a": 0, "w": "Hard to copy because of culture, tacit knowledge and social complexity.", "wn": {"1": "Valuable = it creates value; the question is about copying.", "3": "Culture could be rare, but 'can't be replicated' is the definition of inimitable."}}, {"id": "n80", "t": "intro", "q": "Sustainable HRM (Ehnert et al.) is the adoption of HR strategies and practices that:", "o": ["Only comply with the law", "Focus on shareholders only", "Enable financial, social and ecological goals, inside and outside the firm, over the long term, while controlling for unintended side effects", "Minimise labour costs"], "a": 2, "w": "Reasons: ethics, attracting talent, impressing investors (Stahl et al. 2020).", "wn": {}}, {"id": "n81", "t": "intro", "q": "Patagonia's HR supports its mission mainly by:", "o": ["Minimising pay", "Hiring people who fit the culture and subscribe to the mission, plus benefits aligned to its values", "Hiring purely on technical skills", "Forced ranking"], "a": 1, "w": "A case of HR practices fully aligned with strategy.", "wn": {}}, {"id": "n82", "t": "intro", "q": "Fréry, Lecocq & Warnier ('Competing with ordinary resources') warn that relying on rare 'top talent':", "o": ["Is required by VRIO", "Is costly, and top talent can capture the value it creates", "Guarantees innovation", "Is always cheap"], "a": 1, "w": "Optional reading: ordinary resources are cheap, accessible and compatible with frugal innovation.", "wn": {}}, {"id": "n83", "t": "intro", "q": "Which is listed as a main obstacle to strategy execution?", "o": ["High engagement", "Too many HR business partners", "Unclear roles and responsibilities (accountability) and reward systems not aligned with objectives", "Too much clarity on objectives"], "a": 2, "w": "Obstacles: accountability, motivation, direction, leadership and values, capabilities, monitoring.", "wn": {}}, {"id": "n84", "t": "craft", "q": "Session 6 (Kroezen, craft) asks what a manager would miss by looking only at the final output. The point is that:", "o": ["Only quantity matters", "Craft work carries process, tacit skill, care and identity that output-only measures ignore", "Output metrics capture everything", "Craft is irrelevant to modern firms"], "a": 1, "w": "Links to performance management: deficiency (relevant aspects not measured) and intrinsic rewards.", "wn": {}}, {"id": "n85", "t": "craft", "q": "From an HR perspective, seeing work as an occupation or craft mainly highlights:", "o": ["That jobs should be fully automated", "That pay is the only motivator", "Meaning, identity and skill mastery as sources of motivation and wellbeing", "That forced ranking works best"], "a": 2, "w": "Connects to Herzberg's motivators, EVP meaning and purpose, Warr's opportunity for skill use.", "wn": {}}], "papers": {"1": ["p1-1", "p1-2", "p1-3", "p1-4", "p1-5", "p1-6", "p1-7", "p1-8", "p1-9", "p1-10", "p1-11", "p1-12", "p1-13", "p1-14", "p1-15", "p1-16", "p1-17", "p1-18", "p1-19", "p1-20"], "2": ["n7", "n11", "n15", "n19", "n31", "n35", "n39", "n56", "n60", "n64", "n68", "n44", "n48", "n52", "n2", "n6", "n77", "n81", "n21", "n25"], "3": ["n8", "n12", "n16", "n28", "n32", "n36", "n40", "n57", "n61", "n65", "n69", "n45", "n49", "n53", "n3", "n74", "n78", "n82", "n22", "n26"], "4": ["n9", "n13", "n17", "n29", "n33", "n37", "n41", "n58", "n62", "n66", "n42", "n46", "n50", "n54", "n4", "n75", "n79", "n83", "n23", "n27"], "5": ["n10", "n14", "n18", "n30", "n34", "n38", "n55", "n59", "n63", "n67", "n43", "n47", "n51", "n1", "n5", "n76", "n80", "n20", "n24", "n70"]}, "pcase": {"1": "nova", "2": "lumen", "3": "brightcart", "4": "solvia", "5": null}, "sess": [{"n": 1, "t": "intro", "title": "Introduction to (strategic) HRM", "q": "Why do we need HR managers?", "case": "Patagonia", "theory": ["hrm-def", "shrm", "rbv", "sust", "ulrich"], "read": "Noe et al. ch. 1 (Festing deck); optional Fréry et al."}, {"n": 2, "t": "brand", "title": "Employer branding", "q": "What are companies looking for?", "case": "L'Oréal Brandstorm; Schein career anchors exercise", "theory": ["brand", "psy", "signal", "evp", "sixstep", "anchors"], "read": "Mortensen & Edmondson (2023) — compulsory"}, {"n": 3, "t": "rec", "title": "Recruitment", "q": "Who is a good candidate?", "case": "Recruitment of a Star (RSH: who replaces Peter Thompson?)", "theory": ["intext", "hc", "portab", "stars"], "read": "Groysberg et al. (2006) Are Leaders Portable?"}, {"n": 4, "t": "sel", "title": "Selection, diversity and AI", "q": "Can we avoid being biased?", "case": "Netflix inclusion; Tengai robot; Amazon CV tool", "theory": ["selmeth", "interviews", "errors", "relval", "hurdle", "signal", "ely", "ai", "neuro", "ingram"], "read": "Ingram (2021) — compulsory"}, {"n": 5, "t": "comp", "title": "Rewards and compensation", "q": "What is the best way to reward and motivate people?", "case": "Name Your Price", "theory": ["herz", "vroom", "equity", "intcons", "incent", "pfp", "total"], "read": "Sayre et al. (2026) — compulsory"}, {"n": 6, "t": "craft", "title": "The future of occupations (craft)", "q": "What does an occupation make possible for people, and what does it demand?", "case": "Zine; guest Jochem Kroezen", "theory": ["craft"], "read": "Kroezen (2026) Craft in Organization and Management Studies"}, {"n": 7, "t": "pm", "title": "Performance management", "q": "How can we evaluate people?", "case": "Rob Parson at Morgan Stanley; GE & FCA", "theory": ["pmpurp", "pmcrit", "justice", "relabs", "forced", "capp"], "read": "Cappelli & Tavis (2016) — compulsory"}, {"n": 8, "t": "well", "title": "Wellbeing", "q": "Is the workplace sustainable?", "case": "Yourself", "theory": ["warr", "cooper", "wb3"], "read": "Warr (2017) vitamin model"}], "topics": {"intro": "S1 Intro & strategic HRM", "brand": "S2 Employer branding", "rec": "S3 Recruitment", "sel": "S4 Selection & diversity", "comp": "S5 Compensation", "craft": "S6 Craft", "pm": "S7 Performance mgmt", "well": "S8 Wellbeing"}, "th": {"hrm-def": {"n": "HRM definition", "who": "Boxall & Purcell 2003; Noe et al.", "what": "All management decisions and activities that shape the relationship between the organisation and its employees: the policies, practices and systems that influence behaviour, attitudes and performance.", "use": "Open a case answer by naming which HR practices (recruitment, appraisal, pay…) are shaping the behaviour you see.", "story": "Trick: Boxall & Purcell, picture a BOX of all the deals between a firm and its people. Every HR decision goes in the box.", "ex": "\"The firm's HR practices (recruitment, appraisal, pay) shape employee behaviour and performance (Boxall & Purcell), so the problem here is an HR design problem, not just a people problem.\""}, "shrm": {"n": "Strategic HRM vs traditional personnel", "who": "Wright & McMahan 1992; Succi S1", "what": "Strategic HRM = planned HR activities that help the firm reach its goals. Traditional personnel is short-term, reactive, about compliance and cutting costs; strategic HRM is long-term, proactive, about commitment and investing in people.", "use": "Say whether the firm's HR is aligned with its strategy. A firm whose strategy is innovation but whose HR rewards hours is misaligned.", "story": "Trick: Old-school 'personnel' is the admin office that files contracts and cuts costs. Strategic HRM sits at the strategy table. Wright & McMahan: 'Wright' as in doing the RIGHT things for the strategy.", "ex": "\"X's strategy is innovation, but its HR rewards hours and compliance, which is traditional personnel thinking; strategic HRM (Wright & McMahan) requires HR practices that fit the strategy.\""}, "rbv": {"n": "Resource-based view and VRIO", "who": "Barney 1991/1995", "what": "People give lasting advantage only if they are Valuable, Rare, hard to Imitate and the Organisation is set up to capture their value.", "use": "Argue that culture, teamwork or a unique employer brand are hard to copy, so worth investing in; pay alone is easy to copy.", "story": "Story: Barney's idea is why nobody beats Southwest-style cultures by copying them: you can copy planes and prices, not people and culture. Trick: BARNEY guards a VRIO treasure chest: Valuable, Rare, Inimitable, Organised.", "ex": "\"A committed, skilled workforce is valuable, rare and hard to imitate (Barney's VRIO), whereas pay can be copied overnight, so X should invest in culture and development.\""}, "sust": {"n": "Sustainable HRM", "who": "Ehnert et al. 2016; Stahl et al. 2020", "what": "HR strategies that reach financial, social and ecological goals over the long term, inside and outside the firm, while controlling for side effects such as burnout.", "use": "Use when a practice gets short-term results but burns people out (long hours, up-or-out, uncertain pay).", "story": "Trick: Ehnert sounds like 'energy'. Sustainable HRM means not burning through your people's energy like a fossil fuel. Long-term people, planet and profit.", "ex": "\"Long hours and insecure contracts deliver short-term results but burn out staff; sustainable HRM (Ehnert) asks X to protect its people as a long-term resource.\""}, "ulrich": {"n": "HR as business partner", "who": "Ulrich 1997", "what": "HR moves from staff support to business partner that enables strategy execution: clear roles, aligned rewards, communication of strategy, leadership, capabilities, monitoring.", "use": "Recommend HR involvement in strategy, not just administration.", "story": "Story: In 1996 a Fortune article said 'Blow up the HR department.' Ulrich answered: don't blow it up, turn it into a business partner that helps execute strategy.", "ex": "\"HR at X acts as an administrator; following Ulrich, it should become a business partner involved in executing the strategy.\""}, "brand": {"n": "Employer brand", "who": "Sparrow & Otaye 2015", "what": "The firm's reputation as an employer plus its value proposition to employees. It also works on current employees: manages the psychological contract, signals values and prestige, creates shared identity.", "use": "Check whether the brand message attracts the people the firm actually needs.", "story": "Trick: The employer brand is the firm's dating profile. Sparrow & Otaye: a 'sparrow' singing to attract the right mate, and it has to keep singing to keep current employees.", "ex": "\"X's employer brand is the promise it makes to candidates (Sparrow & Otaye); right now that promise attracts the wrong people.\""}, "psy": {"n": "Psychological contract", "who": "Schein 1980; Sparrow & Cooper 1998", "what": "Unwritten reciprocal expectations between employee and employer, which change over time. If the brand promises something the job doesn't deliver, the contract is breached: disappointment, low commitment, turnover.", "use": "Use whenever external promises don't match the experience inside (exit interviews, early turnover).", "story": "Story: Schein (MIT) called it the 'psychological contract': the unwritten deal in everyone's head. Trick: a job offer is a wedding with a written contract (salary) and an unwritten one (respect, growth). Break the unwritten one and you get a quiet divorce: people leave.", "ex": "\"The brand promised flexibility, but the reality is long hours; this breaches the psychological contract (Schein), which explains the early turnover.\""}, "signal": {"n": "Signalling theory", "who": "Spence 1973; Bowen & Ostroff 2004", "what": "Candidates and employees can't see a firm's real qualities, so they read observable signals: brand messages, who gets promoted, diversity, how people are evaluated. HR practices constantly send messages about what is valued.", "use": "Ask: what does this practice signal? Up-or-out signals 'stay late and be seen'; an all-elite intake signals 'people like us only'.", "story": "Story: Spence won the Nobel Prize (2001) for showing a degree is partly a signal: employers can't see your talent, so they read the diploma. Firms do the same: who they promote and how they hire are signals. Trick: every HR decision is a billboard.", "ex": "\"Promoting a star who bullies juniors signals that results excuse behaviour (signalling theory, Spence), undermining X's culture change.\""}, "evp": {"n": "EVP: four factors", "who": "Mortensen & Edmondson 2023", "what": "Material offerings (pay, perks, flexibility); growth and development; connection and community; meaning and purpose. Material = easiest to copy and least lasting. Short-term vs long-term, individual vs collective. Manage them as a system. Examples: UNICEF (purpose alone turned toxic), Best Buy (purpose first), WD-40 ('Work from Where').", "use": "Show the firm relies on one factor only (usually pay or prestige) and recommend a balanced EVP.", "story": "Story: UNICEF had the most moving purpose on earth (protecting children) and still turned toxic, with bullying and people leaving, because it relied on purpose alone. Mortensen & Edmondson: four legs of a table (money, growth, community, purpose). Remove one and it wobbles.", "ex": "\"X relies only on pay, the easiest EVP factor to copy (Mortensen & Edmondson); like UNICEF, a one-legged EVP backfires, so it should add growth, community and purpose.\""}, "sixstep": {"n": "Six-step employer branding model", "who": "Succi S2", "what": "1 Who am I (identity vs image), 2 know your target, 3 know competitors, 4 distinctive EVP, 5 create and communicate the brand (universities, job sites, social networks, media; L'Oréal Brandstorm), 6 evaluate impact (KPIs: exposure, baseline, engagement; external recognition).", "use": "Structure a branding recommendation in these steps.", "story": "Trick: think of launching a product, but the product is the job. Who am I? Who's my customer? Who are my rivals? What's my unique offer? Advertise. Measure. L'Oréal Brandstorm is step 5 in action.", "ex": "\"Using the six-step employer branding model, X should first close the gap between identity and image, then communicate a distinctive EVP through the right channels and measure the impact.\""}, "anchors": {"n": "Career anchors", "who": "Schein", "what": "What people won't give up in a career: technical competence, managerial, autonomy, security, entrepreneurial creativity, service, pure challenge, lifestyle.", "use": "Explain why one EVP can't attract everyone: different anchors want different deals.", "story": "Story: Schein interviewed MIT alumni for years and found everyone has one career thing they won't give up: their anchor. Trick: a boat (career) moves, but the anchor keeps it in place: security, autonomy, challenge, lifestyle…", "ex": "\"Young consultants anchored in lifestyle and autonomy (Schein) won't be attracted by a message about discipline and long hours.\""}, "intext": {"n": "Internal vs external recruitment", "who": "Succi S3", "what": "Internal: cheaper, easier assessment, career paths and morale; but stagnation and competition. External: new ideas and the right skills; but costly and risky.", "use": "Recommend a mix: promote from within for firm-specific skills, hire externally for new capabilities.", "story": "Trick: internal = the home-grown tomato (cheap, you know it, but same old taste); external = the imported exotic fruit (new flavour, expensive, may rot in transit).", "ex": "\"Promoting internally keeps firm-specific knowledge and morale; hiring externally brings new ideas but at higher cost and risk, so X should…\""}, "hc": {"n": "Human capital theory", "who": "Becker 1964", "what": "Human capital = knowledge, skills, ideas and health of individuals. General skills (portable) vs firm-specific skills (not portable).", "use": "Explain why a star from outside may underperform: much of their value was firm-specific.", "story": "Story: Gary Becker won the Nobel Prize (1992) for treating education and skills like an investment, just like a machine. Trick: Becker = BACKPACK. General skills go in the backpack and travel with you; firm-specific skills stay in your office drawer.", "ex": "\"Much of the star's value is firm-specific human capital (Becker) that stays at the old firm.\""}, "portab": {"n": "Portability of human capital", "who": "Groysberg, McLean & Nohria 2006", "what": "Five types from least to most portable: company-specific, relationship, industry, strategic, general. Nonportability: soft (culture, HR practices), hard (IT systems, data), product-based (products no one else sells).", "use": "Assess a candidate by which human capital will travel with them.", "story": "Story: Groysberg tracked 20 GE executives who became CEOs elsewhere. They did well when the new firm needed the same skills, and badly when it didn't. Trick: some skills pack into a suitcase (general management), some are glued to the old office (company-specific).", "ex": "\"Groysberg shows company-specific and relationship human capital doesn't travel, so X can't assume the star's results will move with her.\""}, "stars": {"n": "The risky business of hiring stars", "who": "Groysberg, Nanda & Nohria 2004", "what": "Study of 1,000+ star analysts: after moving, their performance drops, their new team gets worse and they leave soon despite high pay.", "use": "Argue for developing talent internally (e.g. Rina Shea) and retaining stars.", "story": "Story: Groysberg followed 1,000+ star Wall Street analysts who switched firms. Their performance dropped, their new teams got worse, and many left soon after, despite fat pay packages. Stars are 'transplants that get rejected'.", "ex": "\"Groysberg's study of star analysts shows that performance drops after a move, so X should develop internal talent instead of buying a star.\""}, "selmeth": {"n": "Selection methods", "who": "Succi S4", "what": "Interviews, references, biodata, physical tests, cognitive tests (valid, cheap, legal risk), personality inventories, work samples/assessment centres (seen as fair), honesty/drug tests, medical exams.", "use": "Pick methods that measure what the job needs (validity) and are fair.", "story": "Trick: a selection method is a thermometer. It should measure the right thing (job skills), every time, for everyone, and legally. A work sample is like a test drive.", "ex": "\"Instead of AI-scored videos, X should use work samples and structured interviews, which measure what the job actually needs.\""}, "interviews": {"n": "Interview types", "who": "Succi S4", "what": "Non-directive (unreliable, can drift into illegal questions); structured (most reliable and valid); situational ('what would you do if…'); behaviour description ('tell me about a time…', past predicts future).", "use": "Recommend structured or behaviour description interviews to reduce bias.", "story": "Trick: unstructured interview = a first date (chemistry, random questions, very biased). Structured interview = a driving test (same route, same checklist for everyone). 'Tell me about a time…' = past behaviour predicts future.", "ex": "\"X's unstructured 'fit' interviews are the least reliable format; structured behaviour-description interviews with a scoring rubric would reduce bias.\""}, "errors": {"n": "Interviewer errors and biases", "who": "Succi S4", "what": "Halo/horn, stereotyping, similar-to-me, snap decisions, contrast effect, fundamental attribution error, insufficient information, primacy, social desirability.", "use": "Name the specific bias in the case (e.g. similar-to-me in a homogeneous intake).", "story": "Trick: Halo = one shiny thing blinds you. Similar-to-me = 'reminds me of me at 25!'. Contrast = the candidate after a disaster looks like a genius. Snap decision = judged in the first 4 minutes.", "ex": "\"Managers hiring people who 'fit in on the desk' fall into similar-to-me bias, which explains the homogeneous intake.\""}, "relval": {"n": "Criteria for selection methods", "who": "Noe et al.; Succi S4", "what": "Reliable (free from random error), valid (all relevant and only relevant aspects), generalizable, high utility, legal. Reliability is necessary but not sufficient for validity.", "use": "Use to criticise a method: e.g. visibility-based judgments aren't valid.", "story": "Trick: a bathroom scale that always shows 60 kg is RELIABLE (consistent) but not VALID if you weigh 70. Consistent ≠ correct. The AI that 'treats everyone the same' is that scale.", "ex": "\"Treating everyone the same makes the tool reliable, not valid: it measures camera confidence, not driving ability.\""}, "hurdle": {"n": "Multiple hurdle vs compensatory", "who": "Succi S4", "what": "Multiple hurdle: eliminated at each stage. Compensatory: everyone does all stages; strengths offset weaknesses.", "use": "A compensatory model lets diverse profiles show strengths.", "story": "Trick: multiple hurdle = a hurdle race, trip once and you're out. Compensatory = a decathlon, weak in one event, strong in another, total score counts.", "ex": "\"A compensatory model would let a strong work sample offset a weak interview, helping neurodivergent candidates.\""}, "ely": {"n": "Diversity paradigms", "who": "Thomas & Ely 1996", "what": "Discrimination and fairness (assimilation), then access and legitimacy (differentiation), then learning and effectiveness (integration, the most advanced).", "use": "Argue the firm should move from 'diverse hires for diverse clients' to learning from differences.", "story": "Story: Thomas & Ely's HBR article 'Making Differences Matter' (1996) warns about firms that hire minority staff only to serve matching client groups, boxing them into those niches. Real diversity means learning from their perspectives. Trick: three levels: first 'look fair', then 'look like your customers', finally 'learn from differences'.", "ex": "\"X is stuck at access and legitimacy, using diverse staff only to match clients (Thomas & Ely); it should move towards learning and effectiveness.\""}, "ai": {"n": "AI in recruitment", "who": "Tursunbayeva 2024; Succi S4", "what": "AI learns from past data, so it can copy past bias (Amazon 2018; Aon 2024). Use AI for mechanical tasks, humans for judgment; audit for bias, ask for explainability, keep a human in the loop.", "use": "For any AI question: audit, adjust, human decides.", "story": "Story: Amazon built a CV-screening AI trained on 10 years of mostly male hires. It learned to downgrade CVs containing the word 'women's' (as in 'women's chess club') and was scrapped in 2018.", "ex": "\"Like Amazon's CV tool, which learned to penalise women from past hiring data, X's AI risks reproducing past bias; it needs an audit and a human making the final call.\""}, "neuro": {"n": "Neurodiversity as competitive advantage", "who": "Austin & Pisano 2017", "what": "Neurodiverse talent is screened out by interviews. SAP, HPE and others use non-interview assessments, training and support.", "use": "Recommend alternative assessments where interviews exclude good candidates.", "story": "Story: SAP and HPE found brilliant autistic software testers were being rejected because they didn't do eye contact and small talk in interviews. They replaced interviews with hands-on tasks. Austin & Pisano = 'Austin Powers' of hidden talent.", "ex": "\"Interviews screen out neurodivergent talent (Austin & Pisano); like SAP, X should use practical assessments.\""}, "ingram": {"n": "The forgotten dimension of diversity: class", "who": "Ingram 2021", "what": "Social class background shapes access and advancement but is rarely tracked in diversity efforts.", "use": "Point out that hiring from a few elite schools excludes class diversity, not just gender or ethnicity.", "story": "Story: Paul Ingram (Columbia) notes firms count gender and ethnicity but forget social class: who your parents were. Hiring only from six elite schools is a class filter. Trick: the 'class ceiling'.", "ex": "\"Recruiting from a few elite schools filters out social class, Ingram's forgotten dimension of diversity.\""}, "herz": {"n": "Two-factor theory", "who": "Herzberg", "what": "Hygiene factors (pay, supervision, policies) prevent dissatisfaction but don't motivate; motivators (recognition, responsibility, advancement, the work itself) create satisfaction.", "use": "Explain why competitive salaries don't solve a motivation problem.", "story": "Story: Herzberg asked around 200 engineers and accountants in Pittsburgh about times they felt great and times they felt awful at work. Different things came up! Bad pay made them unhappy, but good pay didn't make them happy. Trick: hygiene = brushing your teeth. Skip it and you get problems; doing it doesn't make you excited.", "ex": "\"X already pays above market, but pay is a hygiene factor (Herzberg): it prevents dissatisfaction without motivating; recognition and growth are missing.\""}, "vroom": {"n": "Expectancy theory", "who": "Vroom", "what": "Motivation = expectancy (my effort leads to performance) × instrumentality (performance leads to reward) × valence (I value the reward). If any is zero, motivation collapses.", "use": "Diagnose which link is broken (e.g. remote staff think good work won't be seen: instrumentality).", "story": "Trick: VROOM is a car with 3 parts. Engine = expectancy (can I do it?), wheels = instrumentality (will I get the reward?), fuel = valence (do I want the reward?). One part missing and the car doesn't move.", "ex": "\"If remote staff believe good work won't be seen, instrumentality is zero, so motivation collapses (Vroom's expectancy theory).\""}, "equity": {"n": "Equity theory", "who": "Adams 1963", "what": "People compare their inputs/outcomes ratio with referents (self or others, inside or outside). If unfair, they change inputs, outcomes or perceptions, switch referent, or leave.", "use": "Use for any pay or promotion unfairness between colleagues.", "story": "Story: J. Stacy Adams developed equity theory while working as a psychologist at General Electric. Trick: you're happy with your €3,000 until you find out your colleague gets €3,500 for the same work. It's not the amount, it's the comparison.", "ex": "\"Paying the newcomer twice what current analysts earn will feel unfair (Adams' equity theory); staff may cut effort or leave.\""}, "intcons": {"n": "Internal consistency vs external competitiveness", "who": "Succi S5", "what": "Internal: job evaluation and pay grades so jobs are paid fairly relative to each other. External: salary surveys and pay policy vs the market.", "use": "Separate 'paid fairly vs colleagues' from 'paid enough vs the market'.", "story": "Trick: internal = fair inside the family (siblings compared to each other); external = fair compared to the neighbours (the market).", "ex": "\"X must ensure internal consistency through job evaluation and pay grades, not only external competitiveness.\""}, "incent": {"n": "Incentive plans", "who": "Succi S5", "what": "Individual (piecework, merit pay, bonuses, commissions), group (gainsharing, team awards), organisational (profit sharing, stock options, ESOPs). Team pay builds cooperation; individual merit pay builds competition and withholding of information (Thompson 1995).", "use": "Recommend team-based rewards where work is team-based.", "story": "Story: Thompson (1995) shows individual merit pay makes people hide information from colleagues. Why help your rival for the bonus? Trick: individual bonus = penalty shoot-out; team bonus = a goal everyone celebrates.", "ex": "\"Individual commissions create competition and withholding of help; a team bonus would reward the cooperation X needs.\""}, "pfp": {"n": "Better pay-for-performance", "who": "Sayre et al. 2026", "what": "The harm comes from pay uncertainty: it causes tunnel vision, longer hours, neglected rest and stress. Fix: clear rules (Adobe), smoothing (Amazon, Boeing), higher base pay with less variable pay (Costco, Target).", "use": "Use whenever bonuses are large and unpredictable.", "story": "Story: In Sayre et al.'s experiments, two groups earned the same on average, but one group's pay was uncertain. That group worked longer, felt worse and skipped rest, and most people preferred certain pay. Costco and Target raised base pay and cut variable pay from 40% to 20%.", "ex": "\"The harm comes from pay uncertainty, not pay-for-performance itself (Sayre et al.), so X should raise base pay and stabilise bonus rules.\""}, "total": {"n": "Total reward", "who": "Succi S5", "what": "Intrinsic (learning, job well done, interest) + extrinsic: financial (direct and indirect) and non-financial (recognition, perks). Expectations matter: reward below expectation reduces behaviour.", "use": "Recommend non-financial rewards (development, recognition), not only money.", "story": "Trick: total reward is a salary plus a backpack of extras: learning, recognition, a job you like. Money is only one pocket.", "ex": "\"Beyond pay, X should use intrinsic and non-financial rewards such as development and recognition.\""}, "craft": {"n": "Craft and occupations", "who": "Kroezen 2026", "what": "Craft = valuing process, skill mastery, care and identity in the work, not only the output.", "use": "Argue that output-only metrics miss key contributions (mentoring, quality, care).", "story": "Trick: a craft baker cares about the dough, not just the number of loaves. Kroezen = 'crust'. Output-only metrics miss the craft.", "ex": "\"Measuring only output misses the craft dimension of the work (Kroezen): skill, care and mentoring.\""}, "pmpurp": {"n": "Purposes of performance management", "who": "Noe et al.; Succi S7", "what": "Strategic, administrative, informational, developmental. Hard to serve all at once; the main purpose shapes the design.", "use": "Point out that a system built for administrative decisions (promote or exit) fails at development.", "story": "Trick: one appraisal trying to be a judge (pay, promote, fire) and a coach (develop) at the same time. People don't open up to a judge.", "ex": "\"X's up-or-out review mixes administrative and developmental purposes, so it fails at development.\""}, "pmcrit": {"n": "Criteria for effective performance management", "who": "Noe et al.", "what": "Fit with strategy, validity (avoid contamination and deficiency), reliability (inter-rater, test-retest), acceptability, specificity.", "use": "Criticise: billable hours = contamination/deficiency; different partners = poor inter-rater reliability.", "story": "Trick: Contamination = rating a footballer on singing. Deficiency = rating a goalkeeper only on goals scored. Inter-rater reliability = two referees should see the same foul.", "ex": "\"Billable hours contaminate the evaluation and teamwork is missing (deficiency); different partners rating differently shows poor inter-rater reliability.\""}, "justice": {"n": "Distributive and procedural justice", "who": "Succi S7", "what": "Distributive = is the outcome fair? Procedural = are the procedures fair? Strengthen with clear criteria upfront, a credible evaluator, a say in the process, no public humiliation.", "use": "Recommend transparent criteria and multiple raters.", "story": "Trick: distributive = was the cake split fairly? Procedural = was the way it was cut fair? People accept a smaller slice if the cutting was fair.", "ex": "\"Even if outcomes stay the same, clear criteria and a voice in the process would strengthen procedural justice.\""}, "relabs": {"n": "Relative vs absolute appraisal methods", "who": "Succi S7", "what": "Relative: ranking, paired comparison (N(N−1)/2), forced distribution. Absolute: graphic rating scales, mixed-standard scales, critical incidents, BARS, 360°, MBO (SMART goals).", "use": "Propose 360° and MBO instead of ranking.", "story": "Trick: relative = a race (you vs others). Absolute = a driving test (you vs a standard). Paired comparison with 15 people = 105 duels (15×14/2).", "ex": "\"X should replace ranking (relative) with absolute methods such as MBO and 360° feedback.\""}, "forced": {"n": "Forced distribution", "who": "GE (Welch 20-70-10), Microsoft", "what": "Drawbacks: horse-trading, infighting and no collaboration, short-termism; Barankay found performance falls when people are rated relative to others. The pioneers have dropped it.", "use": "Use against any up-or-out or stack-ranking system.", "story": "Story: Jack Welch at GE fired the bottom 10% every year ('rank and yank'). Microsoft's stack ranking became infamous: engineers avoided working with strong colleagues so they wouldn't look worse. Both dropped it.", "ex": "\"Like GE and Microsoft, which abandoned forced ranking because it fuelled infighting, X's ranking system will undermine teamwork.\""}, "capp": {"n": "The performance management revolution", "who": "Cappelli & Tavis 2016", "what": "Shift from accountability to development: frequent, informal check-ins following the work cycle. Three reasons: people development, agility, teamwork. Examples: Colorcon, Adobe, Deloitte, GE touchpoints, Gap. Challenges: aligning goals, rewarding performance, poor performers, legal risk. 'Third way': several ratings a year.", "use": "Recommend continuous feedback and team goals, and name a challenge to show balance.", "story": "Story: When Colorcon's HR head told a room of HR executives that they'd stopped doing annual reviews, the audience was appalled. A few years later Adobe, Deloitte and even GE did the same. Cappelli & Tavis: from 'judge once a year' to 'coach all year'.", "ex": "\"Following Cappelli & Tavis, X should replace annual reviews with frequent check-ins focused on development, as Adobe and Deloitte did.\""}, "warr": {"n": "Vitamin model", "who": "Warr 2017", "what": "AD vitamins (too little or too much is bad): control, contact, skill use, external goals, variety, clarity. CE vitamins (too little is bad): money, physical security, valued social position.", "use": "Explain why too much pressure or too many goals harms wellbeing even if some is good.", "story": "Story: Peter Warr compared work features to vitamins. Some (vitamins A and D) are toxic in large doses: too much control or too many goals hurt. Others (C and E) just level off: more money stops helping after a point. Trick: AD = Additional Decrement (too much harms); CE = Constant Effect.", "ex": "\"In Warr's vitamin model, the nurses get too little control and too much externally imposed demand, two 'AD vitamins' out of balance.\""}, "cooper": {"n": "Stress interventions", "who": "Cooper & Cartwright 1997", "what": "Primary: remove stressors (job design). Secondary: stress management (training). Tertiary: rehabilitation (assistance programmes). Corporate vs local.", "use": "Recommend primary interventions over yoga apps.", "story": "Trick: a river is full of rubbish. Primary = stop the factory dumping (fix the job). Secondary = teach people to swim through it (stress training). Tertiary = rescue the drowning (counselling). A meditation app is swimming lessons.", "ex": "\"A meditation app is a secondary intervention; Cooper & Cartwright would prioritise primary interventions that remove the stressor, e.g. staffing.\""}, "wb3": {"n": "Three dimensions of wellbeing", "who": "Warr 1987; Grant 2007", "what": "Psychological, physical, social. Costs of poor wellbeing: absenteeism, turnover, accidents, lawsuits, poor decisions, reputation. Gallup 2025: 21% engaged.", "use": "Make the business case for wellbeing.", "story": "Story: Gallup 2025: only about 1 in 5 employees worldwide is engaged at work. Trick: wellbeing has 3 sides: mind, body, relationships.", "ex": "\"Poor wellbeing has measurable costs (absenteeism, turnover, errors), so investing in it is a business case, not a perk.\""}}, "classc": [["Patagonia", "S1", "HR fully aligned with mission: hiring people who share it, benefits matching values.", "Strategic fit, sustainable HRM, signalling."], ["L'Oréal Brandstorm", "S2", "Student innovation contest used to attract talent; you don't need to win to be hired.", "Employer branding channels (universities), signalling."], ["Recruitment of a Star (RSH)", "S3", "Star analyst Peter Thompson leaves; replace with an outsider or promote junior Rina Shea?", "Human capital portability, internal vs external, equity with other analysts."], ["Netflix", "S1, S4", "'Freedom & Responsibility' culture; inclusion behaviours (focus on talent, not similarity to yourself).", "Signalling, similar-to-me bias, inclusion."], ["Amazon CV tool (2018) and Tengai robot", "S4", "AI trained on past hires penalised women; robot interviewer meant to remove bias, but humans read the transcripts.", "AI bias, human in the loop, validity."], ["Name Your Price", "S5", "Monroe must propose his own pay to Jim; trust and fairness.", "Equity, expectancy, signalling, trust game."], ["Rob Parson at Morgan Stanley", "S7", "Top producer, poor teamwork; 360° in a new 'One-Firm' culture; promote to MD?", "360°, signalling what's valued, development vs accountability."], ["GE and Microsoft", "S7", "Pioneers of forced ranking (vitality curve, 20-70-10) that dropped it; GE moved to 'touchpoints'.", "Forced distribution drawbacks, Cappelli & Tavis."], ["UNICEF, Best Buy, WD-40", "S2", "Purpose alone turned toxic (UNICEF); purpose first (Best Buy); values guide remote work (WD-40).", "EVP as a system."], ["Adobe, Deloitte, Gap, Colorcon", "S7", "Dropped annual reviews for frequent check-ins.", "Moving from accountability to development."]], "cases": [{"id": "nova", "title": "NovaConsulting", "src": "2025 exam paper", "text": "NovaConsulting is a European management consultancy with around 2,000 employees, mainly in Paris, Berlin and Madrid. It has a strong reputation for digital transformation projects, but in recent years it has struggled to attract and retain young professionals.\n\nDespite competitive salaries, recruitment results are disappointing: applications from top universities are falling and more job offers are rejected. Exit interviews suggest candidates and employees see the company as \"traditional\" and less appealing than newer competitors who emphasise flexibility, sustainability and employee wellbeing.\n\nIn response, HR launched an employer branding campaign centred on NovaConsulting's long history, its prestigious clients in finance and industry, and its reputation for rigorous professional standards. The campaign runs on LinkedIn, the company website and university job fairs, where recruiters present NovaConsulting as \"a place to build a solid career through excellence and discipline.\"\n\nRecruitment is mainly done through a narrow set of elite European universities, with assessment centres focused on cognitive ability tests and individual case interviews. Candidates who fit the \"classic consultant profile\" (strong analytical skills, excellent grades, ability to work long hours) are prioritised. This has produced high-calibre recruits but also a fairly homogeneous workforce in background, mindset and career expectations. It no longer seems to resonate with many younger professionals.\n\nNovaConsulting is also reconsidering performance management. For decades it used a classic \"up-or-out\" model: consultants are evaluated once a year and either promoted, kept at the same level or asked to leave. Evaluation is based on feedback from project managers and partners, combined with billable hours and client satisfaction scores. This once reinforced a strong performance culture and fast progression, but now generates growing dissatisfaction.\n\nYounger employees say the system rewards visibility and long hours more than collaboration, innovation or mentoring. In hybrid work, consultants who work remotely feel disadvantaged compared with those in the office, where their effort is more visible. Managers find it hard to evaluate contributions consistently, given team-based projects and subjective judgments. Several partners worry the model fuels stress, undermines cooperation and drives costly turnover.\n\nLeadership faces two challenges: redesigning recruitment and employer branding to attract diverse, motivated candidates, and adapting performance management to ensure fairness and motivation in a hybrid workplace.", "qs": [{"pts": 4, "q": "NovaConsulting's recruitment efforts are failing to attract enough young and diverse candidates. Based on the theories and concepts studied in class, explain why the current employer branding strategy may not be effective.", "check": ["Names at least 2 theories (e.g. psychological contract, signalling theory, EVP four factors, identity vs image)", "Uses case facts: 'history, prestigious clients, excellence and discipline' message; elite universities; long hours; 'traditional' image in exit interviews", "Explains the mismatch: the brand promises what young candidates don't want, while competitors offer flexibility, sustainability, wellbeing", "Covers diversity: narrow channels, classic profile and cognitive tests produce a homogeneous pool (similar-to-me, Ingram's class dimension)", "Mentions a class case (e.g. L'Oréal Brandstorm, UNICEF/WD-40) or ends with a short recommendation"], "model": "1. The EVP is one-dimensional. Mortensen & Edmondson describe four factors: material offerings, growth, connection and community, meaning and purpose. Nova's campaign sells prestige and pay (material offerings plus a status message) and says nothing about community, purpose (sustainability) or wellbeing, which are exactly what exit interviews say young people want. Competitive salaries are easy to copy and, as Herzberg would say, a hygiene factor: they stop dissatisfaction but don't attract or motivate.\n\n2. Wrong signals. Under signalling theory, candidates read the brand to guess how they'll be treated. \"Excellence and discipline\", long history and long hours signal a rigid, hierarchical, high-pressure workplace, confirming the \"traditional\" image. Identity (who Nova is) and image (what candidates see) fit each other, but neither fits the target group.\n\n3. Psychological contract. The campaign creates expectations of a stable career through discipline, while younger candidates expect flexibility and balance (different career anchors, Schein). Rejected offers suggest candidates already sense the contract wouldn't meet their expectations.\n\n4. Narrow channels limit diversity. Recruiting from a few elite schools, a 'classic profile' and cognitive tests create similar-to-me bias and exclude class diversity (Ingram). A homogeneous workforce is itself a signal that 'people like you don't fit'.\n\nRecommendation: rebuild the EVP around growth, community and purpose (e.g. sustainability projects, mentoring), widen channels, and measure impact (step 6: offer-acceptance rate, applications by school)."}, {"pts": 6, "q": "The traditional up-or-out performance management model is increasingly questioned, especially in a hybrid work environment. Drawing on at least two theoretical frameworks, discuss the potential drawbacks of this model and propose alternative approaches that could ensure both fairness and motivation.", "check": ["Names at least 2 frameworks (e.g. Cappelli & Tavis, validity/reliability criteria, procedural vs distributive justice, expectancy theory, forced distribution drawbacks, signalling)", "Drawbacks tied to case facts: once a year; billable hours and visibility; remote staff disadvantaged; team projects; subjective partners; stress and turnover", "Explains why it is unfair (validity: contamination/deficiency; low inter-rater reliability; procedural justice) AND demotivating (expectancy: instrumentality broken for remote staff; equity)", "Proposes concrete alternatives: frequent check-ins, team and individual goals (MBO), 360° feedback, clear criteria, development focus, calibration across raters", "Cites a class case (GE touchpoints, Deloitte, Adobe, Rob Parson) and acknowledges a trade-off (e.g. still need to differentiate pay; 'third way')"], "model": "Drawbacks\n\n1. Poor validity and reliability (Noe et al. criteria). Billable hours and visibility are contamination (measuring things that aren't real performance) and the system is deficient: collaboration, innovation and mentoring aren't measured. Different partners judging subjectively, on team-based work, gives low inter-rater reliability.\n\n2. Unfair in hybrid work. Procedural justice is weak: criteria are unclear and depend on who sees you. Remote consultants are rated lower for being less visible, not for worse work (a proximity bias, close to the halo effect).\n\n3. Demotivating. In Vroom's expectancy theory the instrumentality link is broken for remote staff: good work won't lead to promotion if nobody sees it. Equity theory: comparing themselves to visible office colleagues, they see unfair outcomes and may leave, which matches the turnover.\n\n4. Wrong behaviour and burnout. Like forced distribution, up-or-out creates infighting and short-termism and undermines cooperation. It signals that long hours and visibility are what count. It is not sustainable HRM: stress and turnover are costs.\n\n5. Purpose conflict. One annual review mixes administrative decisions (promote or exit) with development, which Cappelli & Tavis say doesn't work.\n\nAlternatives\n\n- Follow Cappelli & Tavis: frequent, informal check-ins at project milestones, focused on development (Deloitte, GE 'touchpoints', Adobe).\n- Measure what matters: MBO with SMART goals mixing individual and team objectives, plus 360° feedback from peers, juniors and clients (lessons from Rob Parson: teamwork counts, not only revenue).\n- Fair process: clear criteria set upfront, several raters and calibration meetings, output-based criteria so remote and office staff are judged the same way.\n- Replace strict up-or-out with multiple career tracks (e.g. expert track) and team-based bonuses to reward collaboration.\n\nTrade-off: the firm still needs to differentiate pay and identify poor performers; a 'third way' (several lighter ratings a year) keeps that while focusing on development."}]}, {"id": "lumen", "title": "Lumen Bank", "src": "New practice case (selection, AI and diversity)", "text": "Lumen Bank is a mid-sized European investment bank with 4,500 employees in Frankfurt, Milan and Warsaw. Its leadership has publicly committed to \"a workforce that reflects the clients and societies we serve,\" and its careers page shows diverse teams and a new parental-leave policy.\n\nEach year Lumen receives about 30,000 applications for 250 graduate places. To cope with the volume, HR introduced an AI tool last year that screens CVs and scores one-way video interviews. The tool was trained on the profiles of analysts hired over the past ten years and rated as high performers by their managers. Recruiters then hold unstructured interviews with the top candidates; managers say they look for \"people who will fit in on the desk.\"\n\nAfter one cycle, results worry the Diversity Committee: the share of women among hires fell from 38% to 29%; almost all hires come from six business schools; candidates with career breaks or from non-finance degrees are almost never shortlisted. Two neurodivergent candidates with excellent quantitative test scores were rejected after the video interview. Meanwhile, social media posts from rejected candidates describe the process as \"a black box.\"\n\nThe Head of HR argues that the AI is \"objective because it treats every candidate the same,\" and that the drop is a pipeline problem. The CEO wants a plan before the next recruiting season.", "qs": [{"pts": 4, "q": "Explain why Lumen Bank's selection process is producing less diverse hires, despite the bank's public commitment to diversity. Use concepts and theories from class.", "check": ["Explains AI bias: trained on past hires and past manager ratings, so it copies past bias (Amazon 2018)", "Names biases in the human stage: unstructured interviews, 'fit in on the desk' = similar-to-me; low reliability/validity of unstructured interviews", "Links to diversity theory: Ingram (class/elite schools), neurodiversity (Austin & Pisano: interviews screen out talent), Thomas & Ely paradigm", "Signalling / psychological contract: careers page promises diversity, process contradicts it ('black box' posts damage the brand)", "Rebuts 'objective because same treatment' (consistent ≠ valid)"], "model": "1. The AI reproduces the past. It was trained on ten years of hires and on managers' ratings. If those hires were mostly men from a few schools, the model learns that profile as 'high performer' and down-ranks others, like Amazon's CV tool in 2018. Treating everyone 'the same' means applying the same biased rule to everyone: the tool is reliable (consistent) but not valid, because it measures similarity to past hires, not ability to do the job. Reliability is necessary but not sufficient for validity.\n\n2. The human stage adds bias. Unstructured interviews are the least reliable and valid format, and 'people who fit in on the desk' invites similar-to-me bias and stereotyping. Career breaks (often women) and non-finance degrees are filtered out even though they aren't job-relevant criteria.\n\n3. Hidden diversity dimensions. Hiring from six schools narrows social class (Ingram's forgotten dimension). Video interviews disadvantage neurodivergent candidates who don't interview well (Austin & Pisano); the two rejected had excellent quantitative scores, a more valid predictor.\n\n4. Brand mismatch. The careers page signals inclusion, but the process signals the opposite. Rejected candidates calling it a 'black box' shows a breach of the psychological contract the brand created, which hurts future applications. Lumen is stuck in the 'access and legitimacy' paradigm (diverse faces for marketing) rather than learning and effectiveness (Thomas & Ely)."}, {"pts": 6, "q": "Propose a redesign of Lumen Bank's selection process that keeps it efficient at high volume while making it fairer and more valid. Justify your proposals with at least two theoretical frameworks.", "check": ["Keeps AI but for mechanical tasks; bias/validity audit, explainability, human in the loop (Session 4 key messages)", "Validity: criteria from job analysis; work samples/cognitive tests; structured or behaviour description interviews with scoring rubric", "Fairness tools: anonymous CVs, diverse panels, interviewer training, compensatory model rather than strict hurdles", "Inclusion: alternative assessments for neurodivergent candidates; wider sourcing beyond 6 schools (Ingram); return-to-work route", "Evaluation and signalling: track hires by group, transparent communication to candidates; names a trade-off (cost, time, legal)"], "model": "Principle: AI for mechanical tasks, people for judgment, and everything audited.\n\n1. Fix the AI (Session 4; Tursunbayeva 2024). Run a bias and validity audit: check whether scores differ by gender, school or career breaks when performance is equal. Remove proxies (school names, gaps), retrain on job-relevant data, require explainability. Use the tool only to check minimum qualifications and schedule, not to rank on 'fit'. A human makes the final decision.\n\n2. Make the method valid (reliability and validity criteria). Define criteria from a job analysis of the analyst role. Use tests that predict performance (cognitive and numerical tests, a realistic work sample such as a short modelling task) instead of video interviews scored by AI. Replace unstructured interviews with structured behaviour-description interviews ('tell me about a time…') scored with the same rubric by every interviewer.\n\n3. Reduce bias in judgment. Anonymous CVs at the screening stage, diverse interview panels, interviewer training on halo, contrast and similar-to-me effects. A compensatory model lets a strong work sample offset a weaker interview, which helps candidates who don't interview well.\n\n4. Widen the funnel (Ingram; Thomas & Ely). Recruit beyond six schools (more universities, coding bootcamps, returner programmes for career breaks). Offer adapted assessments for neurodivergent candidates, as SAP does (Austin & Pisano). This moves Lumen towards the learning-and-effectiveness paradigm.\n\n5. Signal and measure. Tell candidates how AI is used and who decides (transparency closes the 'black box'), and track shortlist and hire rates by group each cycle (step 6 of employer branding). Consistent messages and practice strengthen the psychological contract.\n\nTrade-offs: more human review costs time and money at 30,000 applications; the audit and work samples must be prioritised at the shortlist stage to stay efficient. There is also legal risk if tests have unjustified adverse impact, so they must be validated."}]}, {"id": "brightcart", "title": "BrightCart", "src": "New practice case (compensation and performance management)", "text": "BrightCart is a fast-growing online grocery company with 1,200 employees in Spain and Portugal: warehouse pickers, delivery drivers, and a 150-person B2B sales team selling to restaurants and offices.\n\nSales staff earn a low base salary (about 40% of total pay) and a large monthly commission based only on their individual revenue. Commission rates change every quarter, and new targets are announced by email at the start of each month. Top sellers earn three times as much as average sellers. Leads are assigned by managers, and staff complain that the best leads go to \"favourites.\" Sales staff are ranked monthly on a public leaderboard; the bottom 10% each quarter are put on an improvement plan, and many leave.\n\nWarehouse pickers are paid per order picked (piece rate). Productivity has risen, but so have picking errors, customer complaints and minor injuries. Pickers say they skip breaks to make a decent wage.\n\nTurnover is 45% a year in sales and 60% in the warehouse. An engagement survey shows high stress, low trust in managers and little cooperation: experienced salespeople no longer help new colleagues. The CFO points out that total pay costs are already above the market average and asks why \"paying people well for performance\" isn't working.", "qs": [{"pts": 4, "q": "Using motivation theories studied in class, explain why BrightCart's pay-for-performance system is not producing the motivation and results management expected.", "check": ["Expectancy theory: unclear/changing targets and favouritism break expectancy and instrumentality", "Equity theory: comparison with 'favourites' and 3x top earners; reactions (withdraw effort, leave)", "Sayre et al.: pay uncertainty (low base, changing rates) causes stress, tunnel vision, skipped rest", "Herzberg: pay is hygiene; no motivators (recognition, growth); or output pay quality-vs-quantity problem for pickers", "Uses case numbers (40% base, 45%/60% turnover, errors and injuries)"], "model": "1. Expectancy theory (Vroom). Motivation needs all three links. Expectancy is weak because targets and commission rates change every month and quarter, so staff can't see how effort turns into performance. Instrumentality is broken by lead allocation: if the best leads go to favourites, performance depends on the manager, not on effort.\n\n2. Equity theory (Adams). Sales staff compare their inputs and outcomes with 'favourites' who get better leads and earn three times more. Seeing this as unfair, they reduce effort, stop helping colleagues or leave (45% turnover).\n\n3. Pay uncertainty (Sayre et al. 2026). With only 40% fixed pay and constantly changing rules, income is unpredictable. Their experiments show it is uncertainty, not PFP itself, that harms people: financial insecurity leads to tunnel vision, longer hours and neglected rest. Pickers skipping breaks and the high stress scores match this.\n\n4. Output pay without quality. Piece rates reward quantity, so errors and injuries rise: the classic output-based pay problem of defining output as quantity, not quality. Herzberg: pay is a hygiene factor. Paying above market prevents dissatisfaction, but with no motivators (recognition, growth, responsibility) it doesn't create engagement. That's why spending more isn't working."}, {"pts": 6, "q": "Recommend how BrightCart should redesign its reward and performance management system for both the sales team and the warehouse. Justify with at least two frameworks and discuss possible trade-offs.", "check": ["Smooth and stabilise pay: higher base, smaller and predictable variable pay, clear rules announced in advance (Sayre: Adobe, Costco/Target, Amazon)", "Team/group incentives (gainsharing, team bonus) to restore cooperation (Thompson); quality and safety in pickers' criteria", "Replace public ranking and bottom-10% with fair process: transparent lead allocation, clear criteria (procedural justice), coaching (forced distribution drawbacks; Cappelli & Tavis)", "Non-financial rewards / total reward and wellbeing (Herzberg motivators, Warr, primary interventions on breaks/injuries)", "Trade-offs: cost, risk of losing top sellers, weaker short-term push; how to measure success (turnover, errors)"], "model": "Sales team\n\n1. Reduce pay uncertainty (Sayre et al.). Raise base pay to about 70–80% of total pay, cut the variable share, and fix commission rules for a year, discussed in advance (like Adobe's clear expectations; Costco and Target cut PFP from 40% to 20%). Smooth payouts by averaging over a quarter or more (Amazon, Boeing). This restores expectancy: people know what they need to do.\n\n2. Fix fairness (equity theory; procedural justice). Allocate leads by a transparent rule (rotation or territory), publish the criteria and let staff see their data. This removes the favourites problem and the broken instrumentality link.\n\n3. Reward cooperation. Add a team bonus or gainsharing on team revenue and customer retention, and recognise mentoring of new hires. Team pay encourages information sharing, while pure individual merit pay drives competition (Thompson 1995).\n\n4. Drop the public leaderboard and the bottom-10% rule. Like forced distribution, they cause infighting and short-termism; Barankay found relative ratings reduce performance, and GE and Microsoft abandoned them. Use monthly coaching check-ins focused on development (Cappelli & Tavis); low performers get training or reassignment first.\n\nWarehouse\n\n5. Move from straight piece rate to an hourly base plus a team bonus that counts accuracy and safety, not only volume. This fixes the quantity-vs-quality problem and stops people skipping breaks.\n\n6. Wellbeing as a primary intervention (Cooper & Cartwright): protected breaks, ergonomic support, job rotation. In Warr's terms, too much externally imposed pace is a harmful 'vitamin'.\n\nTotal reward: add development paths (picker to team lead, junior to key account), recognition, training (Herzberg's motivators and EVP growth).\n\nTrade-offs: higher fixed costs and a risk that top sellers leave for pure-commission rivals; a short-term dip in volume. Success measures: turnover, error and injury rates, engagement, sales per head over a year."}]}, {"id": "solvia", "title": "Solvia Biotech", "src": "New practice case (recruitment, human capital, EVP and wellbeing)", "text": "Solvia Biotech is a 600-person research company in Basel developing cancer drugs. Its head of oncology research, Dr. Weber, has just left for a large competitor, taking two senior scientists with him. A key clinical-trial milestone is due in nine months.\n\nThe CEO wants to hire a \"star\" from a rival: Dr. Kaya, a celebrated researcher with many publications, who is asking for double Dr. Weber's salary and a team of ten new hires. Internally, Dr. Lenz, who has worked at Solvia for eight years and knows its lab systems, trial data and partners well, has been leading the team temporarily. Colleagues respect her, but she has a weaker publication record and has never managed a large team.\n\nSolvia has always attracted scientists with its mission (\"medicines that matter\") and its collaborative culture. However, a recent survey shows that researchers feel exhausted: workloads have grown since the departures, goals keep changing as the strategy shifts, and many say they have \"no time to think.\" Several researchers say they would leave if a new boss were paid \"twice what any of us earns.\" The HR director worries that the company is about to make an expensive mistake.", "qs": [{"pts": 4, "q": "Using concepts from class, discuss the risks and benefits of hiring Dr. Kaya compared with promoting Dr. Lenz.", "check": ["Human capital theory: general vs firm-specific; Groysberg's 5 types; soft/hard nonportability applied to Kaya vs Lenz", "Groysberg, Nanda & Nohria: stars' performance drops after moving; team effect; they leave", "Equity theory: doubling salary vs colleagues; risk of departures", "Internal vs external recruitment pros and cons; link to Recruitment of a Star (Rina Shea)", "Balanced conclusion (e.g. promote Lenz with support, or hire only with conditions)"], "model": "Hiring Dr. Kaya (external)\n+ Brings strong general and industry human capital, new ideas and prestige that may attract other scientists (external recruitment's main benefit).\n− Much of her success may not travel. In Groysberg's terms, company-specific and relationship human capital (her old team, lab systems, data) stays behind: soft and hard nonportability. Studies of star analysts show performance falls after a move, the new team gets worse, and stars leave quickly despite high pay.\n− Equity theory: paying her twice what anyone earns will feel unfair; researchers already say they'd leave. Ten new hires also disrupt a collaborative culture just before a deadline.\n\nPromoting Dr. Lenz (internal)\n+ Strong firm-specific human capital (systems, trial data, partners), exactly what matters for a milestone in nine months. Internal promotion is cheaper, easier to assess, and signals career paths, which supports morale and the psychological contract.\n− Weaker publication record and no experience leading a large team; the risk of stagnation and fewer new ideas.\n\nLike Rina Shea in 'Recruitment of a Star', the internal candidate is the safer bet for continuity. Conclusion: promote Lenz with leadership coaching and add targeted external hires for missing skills, or hire Kaya only with a fair pay structure and no wholesale team replacement."}, {"pts": 6, "q": "Beyond filling this position, what should Solvia do to retain its researchers and keep them healthy and motivated? Use at least two frameworks.", "check": ["EVP four factors: protect meaning/purpose and community, add growth (career paths), keep material offerings fair (Mortensen & Edmondson; UNICEF warning)", "Wellbeing: Warr vitamins (clarity, control, external goals too high), Cooper & Cartwright primary interventions", "Performance management: clear, stable goals; frequent check-ins (Cappelli & Tavis); specificity", "Pay: internal consistency/pay grades, equity; avoid huge gaps; team recognition", "Uses case facts (exhaustion, changing goals, milestone, threats to leave) and names a trade-off or priority order"], "model": "1. Rebalance the EVP (Mortensen & Edmondson). Solvia's attraction rests on meaning and purpose plus community. These are hard to copy (VRIO), but UNICEF shows purpose alone can turn toxic when people are overloaded. Add growth and development (a scientific career track alongside the management track, mentoring) and keep material offerings fair rather than spectacular.\n\n2. Treat wellbeing at the source (Cooper & Cartwright). Use primary interventions: redistribute workload, hire temporary support or postdocs for the milestone, cut low-value tasks. Secondary measures (stress training) alone won't fix a structural overload.\n\n3. Restore the right 'vitamins' (Warr). Environmental clarity is missing (goals keep changing), externally imposed goals are too many, and opportunity for control is too low ('no time to think'). Stable priorities and some protected research time put these back in the healthy range.\n\n4. Performance management for development (Cappelli & Tavis; specificity criterion). Replace shifting targets with short-term priorities agreed in regular check-ins, team goals for the trial milestone, and recognition of collaboration.\n\n5. Fair pay (equity theory; internal consistency). Use pay grades from job evaluation so a new leader's pay is explainable relative to others; consider a team milestone bonus that everyone shares, which rewards cooperation and avoids uncertainty-driven stress (Sayre et al.).\n\nPriority: first workload and clarity (the cause of exhaustion), then career paths and fair pay. Trade-off: temporary hires and protected time cost money and may slow the milestone in the short term, but losing more scientists would cost far more (turnover, lost firm-specific knowledge)."}]}], "cc": [{"id": "patagonia", "name": "Patagonia", "sess": "S1 · Intro", "idea": "A company whose HR practices are built around its mission. It's the textbook example of HR aligned with strategy.", "problem": "How can the HR function support a strategy built on a strong environmental mission, so the mission is lived inside the firm and not just written on the website?", "plan": "HR practices pull in the same direction as the mission. Recruitment hires people who fit the culture and believe in the mission. Compensation and benefits were early adopters of things like flexible working hours, consistent with the values.", "result": "Yes. In class it is shown as a positive example: HR practices fully aligned with strategy. The culture and shared commitment it creates are hard for competitors to copy.", "lessons": ["HR creates value when the practices form a consistent system that fits the strategy (strategic HRM, best fit).", "A culture that is valuable, rare and hard to imitate is a source of competitive advantage (RBV, VRIO).", "Hiring for values sends a strong signal to candidates and staff (signalling).", "Sustainable HRM: social and ecological goals sit next to financial ones."], "th": ["shrm", "rbv", "sust", "signal"], "line": "Like Patagonia, whose HR practices (hiring for mission fit, values-based benefits) are fully aligned with its strategy, X should…"}, {"id": "loreal", "name": "L'Oréal Brandstorm", "sess": "S2 · Employer branding", "idea": "An international innovation competition L'Oréal runs every year, used as an employer branding tool to reach students.", "problem": "Big firms compete for the best graduates. How do you get talented students to know you, like you, and picture themselves working for you before they even apply?", "plan": "Every year students from all over the world tackle a real L'Oréal business case, gain skills, meet experts and have a memorable experience. You don't need to win to be hired, so taking part is itself a route in.", "result": "It works as a channel (step 5 of the six-step model: communicate the brand through universities). Students get a real preview of the work, which sets realistic expectations.", "lessons": ["Employer branding is about experience, not only adverts: letting candidates do real work is a strong, credible signal.", "A realistic preview builds an accurate psychological contract, so fewer surprises and less early turnover.", "Universities are a key channel, but if you only use elite ones you narrow diversity (link to Ingram)."], "th": ["brand", "sixstep", "signal", "psy"], "line": "X could follow L'Oréal's Brandstorm approach: give students a real business case to work on, which communicates the brand through universities and sets realistic expectations (psychological contract)."}, {"id": "rsh", "name": "Recruitment of a Star (RSH)", "sess": "S3 · Recruitment", "idea": "An investment research firm loses its star analyst and must decide whether to hire another star from outside or promote from within.", "problem": "At Rubin, Stern and Hertz (RSH), star semiconductor analyst Peter Thompson resigns without notice to join a competitor, just before an important deal (PowerChip). Research Director Stephen Connor must replace him fast. Candidates: outsiders David Hughes, Gerald Baum, Sonia Meetha and Seth Horkum, or Peter's junior analyst Rina Shea, whom he temporarily promoted.", "plan": "Connor uses a headhunter and recruiters to find external stars while Rina covers the sector. The class role-play argued for and against each candidate. The committee's questions: what makes each a strong or risky hire, how much of their human capital will travel to RSH, internal or external, and at what price (is it fair for the other analysts)?", "result": "The case leaves the decision open; the point is how you justify it. Groysberg's research gives the warning: stars who move usually perform worse, their new team gets worse, and they leave quickly. That makes Rina Shea, who knows RSH's clients and systems, a strong option if she gets support.", "lessons": ["A star's success is partly firm-specific (team, systems, clients), and that part doesn't travel (human capital portability).", "External hires bring new ideas but are costly and risky; internal promotion builds career paths and morale.", "Paying a newcomer far more than existing analysts creates equity problems.", "Develop and retain talent rather than relying on buying stars."], "th": ["hc", "portab", "stars", "intext", "equity"], "line": "As in Recruitment of a Star, where RSH had to choose between buying a star and promoting Rina Shea, much of a star's value is firm-specific (Groysberg), so X should…"}, {"id": "netflix", "name": "Netflix", "sess": "S1 & S4 · Strategy, selection and diversity", "idea": "A company that uses its culture ('Freedom & Responsibility') and inclusion behaviours as signals of what it values.", "problem": "How do you build a high-performing, diverse workforce without hiring people who are just like the people already there?", "plan": "Netflix publishes its culture and, under 'inclusion', the behaviours it expects. For example: collaborate effectively with people of diverse backgrounds, nurture and embrace different perspectives, and recognise that we all have biases.", "result": "In class it's used as an example of signalling: by making these values public (jobs.netflix.com/inclusion), Netflix tells candidates and staff what counts. The class question was what this signals and whether practice matches the message.", "lessons": ["HR practices and published values are signals: they shape who applies and how people behave.", "Inclusion means fighting similar-to-me bias in selection, not just stating values.", "The signal only works if daily practice matches it; otherwise the psychological contract breaks."], "th": ["signal", "errors", "ely"], "line": "Like Netflix, which publishes the inclusion behaviours it expects, X should make clear what it values, because HR practices signal to candidates who belongs (signalling theory)."}, {"id": "ai", "name": "Amazon CV tool, Tengai robot, Aon", "sess": "S4 · Selection and AI", "idea": "Three attempts to use technology in hiring, showing that AI can remove bias or reproduce it.", "problem": "Recruiters deal with huge numbers of applications and human bias. Can AI make hiring faster (time to hire) and better (quality of hire) and fairer?", "plan": "Amazon (2018): a CV-screening tool trained on 10 years of past hires. Tengai (Sweden, 2019): an interview robot designed to ignore age, looks, gender, ethnicity and accent, asking every candidate the same questions in the same order; recruiters then read the transcripts and decide. Aon (2024): AI hiring tests.", "result": "Amazon: no. The tool learned from mostly male past hires to penalise women, and it was scrapped. Aon: an ACLU complaint alleged the tests discriminated on disability and race. Tengai: promising (structured, identical questions), but bias can come back when humans read the transcripts, there are few independent evaluations, and it's unclear if a robot can judge soft skills.", "lessons": ["AI learns from past data, so past bias becomes future bias.", "Consistent isn't the same as valid: a tool can be reliable but measure the wrong thing.", "Let AI do mechanical tasks (screening qualifications, scheduling); keep humans for judgment.", "Audit for bias, ask for explainability, keep a human in the loop."], "th": ["ai", "relval", "errors"], "line": "Like Amazon's CV tool, which learned from ten years of past hires to penalise women, X's tool risks reproducing past bias, so it needs a bias audit and a human making the final decision."}, {"id": "nyp", "name": "Name Your Price", "sess": "S5 · Compensation", "idea": "An employee is asked to set his own pay. It's a test of trust, fairness and motivation.", "problem": "Monroe has to draft a proposal to Jim saying what he should be paid. Ask too much and he damages trust; ask too little and he undervalues himself and may feel unfairly treated later. The class question: what one piece of advice would you give Monroe?", "plan": "The class compared it with a scene from the TV show Taxi, where a wealthy father gives Louie a blank cheque to name a fair amount (the trust game). The choice reveals whether he behaves fairly when trusted. Motivation theories are then used to judge what a fair, motivating proposal looks like.", "result": "There is no single right number: the case is about reasoning. A good proposal is benchmarked to the market (external competitiveness), fair compared with colleagues (equity) and linked to clear performance expectations (expectancy). That protects trust in both directions.", "lessons": ["Pay is about fairness and trust, not only the amount (equity theory).", "Benchmark against the market and against colleagues (external competitiveness and internal consistency).", "A clear link between performance and reward motivates (expectancy theory).", "Money is a hygiene factor; growth and recognition are the motivators (Herzberg)."], "th": ["equity", "vroom", "intcons", "herz"], "line": "As in Name Your Price, pay has to be seen as fair compared with others (Adams' equity theory), so X should…"}, {"id": "parson", "name": "Rob Parson at Morgan Stanley", "sess": "S7 · Performance management", "idea": "A top producer with poor behaviour, judged by a new 360° system meant to change the culture. Should he be promoted?", "problem": "From 1993 Morgan Stanley was turning into a 'One-Firm Firm' (teamwork, cooperation, cross-selling) and introduced 360° evaluation for over 2,000 professionals. Paul Nasr hired Rob Parson to 'shake up the culture' and almost implicitly promised him promotion to Managing Director. Parson's results were outstanding: market rank from 10th (2% share) to 3rd (12.2%), new clients, clients love him. But the 360° shows low scores for adherence to policies (2.0 from superiors) and team-player skills (2.5), with comments like 'abrasive' and 'very difficult to work with'. He also broke internal policy, causing a $20,000 error.", "plan": "Nasr must decide whether to put Parson up for MD, write his evaluation summary, and give feedback that keeps him at the firm and helps him improve.", "result": "The case is open, and the class debated for and against. For: results, clients, an implicit promise, and the risk he leaves. Against: MDs are 'standard bearers' of the new culture, so promoting him signals that results excuse bad behaviour, which undermines the One-Firm change. A middle way is to delay the promotion with a clear development plan and coaching.", "lessons": ["What you promote signals what the firm really values (signalling).", "Measuring only results is deficient; a 360° captures teamwork and behaviour.", "Feedback must be specific and developmental to change behaviour.", "Separate the development purpose from the administrative decision (promotion) where possible."], "th": ["signal", "relabs", "pmpurp", "pmcrit", "justice"], "line": "Like Rob Parson at Morgan Stanley, a star producer who scored low on teamwork in the 360°, rewarding results alone would signal that behaviour doesn't matter, so X should…"}, {"id": "forced", "name": "GE and Microsoft: forced ranking", "sess": "S7 · Performance management", "idea": "The pioneers of forced ranking ('stack ranking'), and why they dropped it.", "problem": "How do you push performance up across a huge company and make tough decisions about who to promote, reward or let go?", "plan": "GE under Jack Welch used the 'vitality curve': 20% top, 70% middle, 10% bottom, with the worst 10% removed every year. Microsoft used a similar ranking every six months that decided promotions, bonuses or 'just survival'.", "result": "Not in the long run: none of these pioneers still use forced distribution. Its downsides are horse-trading between managers, infighting and no collaboration, and short-termism. Research (Barankay) found performance falls when people are rated against each other. GE moved to frequent 'touchpoints' (Cappelli & Tavis).", "lessons": ["Ranking people against each other kills cooperation in team-based work.", "Forced ranking may suit a one-off restructuring, but not as a permanent system.", "The move is from accountability to development (Cappelli & Tavis)."], "th": ["forced", "relabs", "capp"], "line": "GE and Microsoft, the pioneers of forced distribution, dropped it because it fuelled infighting and short-termism, so X's up-or-out ranking risks the same."}, {"id": "capp", "name": "Adobe, Deloitte, Colorcon, GE, Gap", "sess": "S7 · Reading: Cappelli & Tavis", "idea": "Companies that dropped annual performance reviews for frequent, informal feedback.", "problem": "Annual reviews were slow, backward-looking, focused on ranking and accountability, and hated by managers and employees. In fast-changing, team-based work, goals set once a year lost meaning.", "plan": "Colorcon gave instant feedback tied to individual goals plus small weekly bonuses. Adobe was the first big departure, building in constant assessment and feedback ('check-ins'). Deloitte followed in 2015, as did Accenture and KPMG. GE introduced 'touchpoints', linked to its FastWorks agile approach.", "result": "Mostly yes for development, agility and teamwork, the three business reasons Cappelli & Tavis give. Challenges remain: aligning individual and company goals, rewarding performance fairly, identifying poor performers and avoiding legal trouble. Some firms (e.g. Gap) found they still need some ratings, so a 'third way' uses several lighter ratings a year.", "lessons": ["Feedback should follow the natural cycle of the work, not the calendar.", "Development and team goals over ranking individuals.", "You still need a way to differentiate pay and handle poor performance."], "th": ["capp", "pmpurp", "justice"], "line": "Following Cappelli & Tavis, and firms like Adobe and Deloitte that replaced annual reviews with frequent check-ins, X should…"}, {"id": "evp", "name": "UNICEF, Best Buy, WD-40", "sess": "S2 · Reading: Mortensen & Edmondson", "idea": "Three examples showing the employee value proposition (EVP) only works as a balanced system of four factors.", "problem": "Firms often try to attract and keep people with one lever, usually pay, perks or flexibility, or sometimes purpose alone.", "plan": "UNICEF relied on its powerful purpose (protecting the world's children). Best Buy under Hubert Joly (from 2012) put purpose first ('enriching customers' lives through technology') but didn't cut staff or wages; it also invested in culture, training and better perks. WD-40 under Garry Ridge met employees' wish for remote work with 'Work from Where': work from anywhere, but use company values (e.g. contributing to the community) to decide when to come in.", "result": "UNICEF: no. Investigations in 2018–19 found its 'results at all costs' culture encouraged bullying and harassment and drove departures, so it launched initiatives on development and community. Best Buy: yes, a turnaround built on an integrated EVP. WD-40: yes, 90% said culture improved, and engagement has been over 90% for 22 years.", "lessons": ["Any single factor in isolation can backfire, even purpose.", "Material offerings are the easiest to copy and the least lasting.", "Leaders should ask how a change to one factor affects the others."], "th": ["evp", "psy", "brand"], "line": "As Mortensen & Edmondson show with UNICEF, relying on one EVP factor can backfire, so X should balance material offerings with growth, community and purpose."}, {"id": "sayre", "name": "Adobe, Amazon, Boeing, Costco, Target (pay)", "sess": "S5 · Reading: Sayre et al.", "idea": "Firms that made pay-for-performance (PFP) work by reducing pay uncertainty.", "problem": "Sayre et al.'s experiments show that PFP harms people through uncertainty: financial insecurity leads to tunnel vision, longer hours, stress and neglected rest. Most people prefer certain pay.", "plan": "Three fixes: write clear rules (Adobe, clear expectations); smooth uncertain income (Amazon uses longer evaluation periods, Boeing companywide bonuses); ease financial insecurity by raising base pay and cutting the variable share (Costco, Target, from about 40% to 20%).", "result": "Presented as good practice: PFP keeps its motivating effect without the harm of unpredictable income.", "lessons": ["The problem is uncertainty, not PFP itself.", "Clear, stable rules restore the link between effort and reward (expectancy).", "A higher base share protects wellbeing."], "th": ["pfp", "vroom", "incent"], "line": "Sayre et al. show the harm of PFP comes from pay uncertainty, so X should raise base pay and smooth bonuses, as Costco and Target did."}], "dr": [{"id": "verso", "title": "Verso Games", "tag": "EVP · wellbeing · psychological contract", "pts": 6, "text": "Verso Games is a 300-person video game studio in Lyon. Its careers page says: \"Make games players love, with a team that feels like family.\" It pays slightly below the big studios but has always attracted passionate young developers.\n\nBefore every release, teams go into \"crunch\": 60–70 hour weeks for two to three months, with pizza dinners in the office and a bonus if the game launches on time. Release dates are set by the publisher and often move forward at short notice. In the last year, 22% of developers left, mostly in their first two years. Exit interviews say \"I loved the games, not the hours\" and \"they sold us a family, we got a factory.\" The CEO's answer is to raise the launch bonus.", "q": "Why is Verso Games losing young developers, and what should it do instead of raising the launch bonus?", "parts": [["Theory 1: Psychological contract (Schein 1980)", "psy", "Verso's brand ('a team that feels like family') sets expectations of belonging and care. Crunch, 60–70 hour weeks and release dates moved at short notice break that unwritten deal. Exit interviews say it directly: 'they sold us a family, we got a factory'. A breached contract explains why people leave in their first two years: the gap between promise and reality is felt early."], ["Theory 2: EVP four factors (Mortensen & Edmondson 2023)", "evp", "Verso attracts with meaning and purpose ('games players love') and connection, but pays below market, and crunch destroys the community it promises. Raising the bonus only adds a material offering, the easiest to copy and the least lasting, and it doesn't touch the reason people leave. Mortensen & Edmondson argue the four factors must work as a system."], ["Theory 3 (bonus): Warr's vitamin model", "warr", "External demands (deadlines set by the publisher) and low control over hours are 'AD vitamins' in harmful excess. Pizza dinners are a secondary fix; the stressor itself stays (Cooper & Cartwright: primary interventions remove the stressor)."], ["Class case", "", "Like UNICEF, whose powerful purpose promoted in isolation produced a 'results at all costs' culture and many departures, Verso's passion-for-games purpose is being used to justify overwork. UNICEF's fix was to balance purpose with development and community."], ["Recommendation", "", "1) Primary intervention: plan releases with buffer, cap overtime and negotiate realistic dates with the publisher. 2) Rebalance the EVP: protect community (no crunch culture), add growth (career paths, mentoring), and bring pay closer to market. 3) Align the brand with reality, or the contract breaks again. 4) Measure first-year turnover and engagement each release. Trade-off: slower releases and higher costs, but lower turnover saves hiring and keeps firm-specific skills."]], "cites": ["unicef"]}, {"id": "nordlicht", "title": "Nordlicht Hotels", "tag": "Recruitment · bias · diversity", "pts": 4, "text": "Nordlicht is a chain of 40 boutique hotels in Germany and Austria. 85% of new staff are hired through employee referrals: employees get €500 for each friend hired. Managers like it because referrals are fast, cheap and \"fit the team.\" Staff turnover is low.\n\nBut 60% of guests are now international, and reviews mention staff who struggle with languages and with guests from other cultures. Almost all front-desk staff are German or Austrian, in their 20s, from the same hospitality schools. Applications from outside the referral network are rare, and the few who apply say the hiring process \"felt like a club.\"", "q": "Explain the risks of Nordlicht's referral-based recruitment, using theories from class.", "parts": [["Theory 1: Similar-to-me bias and selection errors", "errors", "Referrals and 'fit the team' judgments favour people like the current staff. The result is visible: same nationality, age and schools. 'Felt like a club' is how similar-to-me bias looks from outside. Fit is not a valid criterion unless it is defined by the job (e.g. languages, intercultural skills)."], ["Theory 2: Signalling theory", "signal", "A homogeneous front desk and a closed process signal to outside candidates that 'people like you don't belong', which is why few apply. It also signals to international guests that the hotel isn't made for them."], ["Theory 3: Diversity paradigms (Thomas & Ely 1996)", "ely", "Nordlicht isn't even at 'access and legitimacy' (diverse staff to serve diverse markets), although its guest base clearly needs it. Moving towards 'learning and effectiveness' would bring language and cultural knowledge into how service is designed."], ["Class case", "", "Netflix publishes the inclusion behaviours it expects, such as valuing different perspectives, to counter exactly this 'hire people like us' trap."], ["Recommendation", "", "Keep referrals for some roles (they are cheap and give good retention) but cap them. Add external channels: international hospitality schools, job boards abroad. Use structured interviews with job-based criteria (languages, guest handling) and diverse panels. Trade-off: slower, more expensive hiring."]], "cites": ["netflix"]}, {"id": "payly", "title": "Payly", "tag": "Performance management · forced ranking", "pts": 6, "text": "Payly, a Berlin fintech with 900 employees, grew fast but now has to cut costs. The new COO introduces a \"top-grading\" system: every six months, managers must rank their teams. The top 15% get large bonuses; the bottom 10% are put on exit plans. Ratings are based on individual targets.\n\nPayly's products are built by cross-functional squads of engineers, designers and product managers. Six months in, engineers report that colleagues no longer review each other's code carefully, two strong designers left after being ranked \"bottom\" in high-performing squads, and managers spend days negotiating who goes into which category. The COO says: \"GE did it under Jack Welch and became the most valuable company in the world.\"", "q": "Evaluate Payly's new performance management system and recommend an alternative.", "parts": [["Theory 1: Forced distribution and its drawbacks", "forced", "Forced ranking creates horse-trading (managers negotiating for days over categories), infighting (no more careful code reviews) and short-termism. In squads, individual targets can't capture team work, so strong people in strong teams are pushed to 'bottom': two designers left for exactly that reason. Barankay found performance falls under relative ratings."], ["Theory 2: Validity and justice (Noe et al.)", "pmcrit", "Individual targets in team-based work are deficient (collaboration isn't measured) and contaminated (the score depends on who else is in your squad). Procedural justice is weak: the outcome depends on a forced quota, not on clear criteria. Distributive justice is weak too: good performers get exit plans."], ["Theory 3: The performance management revolution (Cappelli & Tavis 2016)", "capp", "Firms dropped annual ranking for three reasons that fit Payly: people development, agility and teamwork. Squads that iterate quickly need frequent feedback, not a six-month stack ranking."], ["Class case", "", "The COO's own example backfires: GE (vitality curve, 20-70-10) and Microsoft both dropped forced distribution; none of the pioneers still use it, and GE moved to frequent 'touchpoints'."], ["Recommendation", "", "Replace ranking with frequent squad check-ins, MBO with team and individual goals, and 360° feedback from squad members. Handle cost cuts with a separate, transparent decision, not disguised as performance ranking. Keep a 'third way' (a few ratings a year, calibrated across managers) to differentiate pay. Trade-off: it is harder to identify poor performers quickly, so managers need training to handle them case by case."]], "cites": ["forced", "capp"]}, {"id": "bean", "title": "Bean & Co", "tag": "Compensation · motivation · PFP", "pts": 4, "text": "Bean & Co runs 120 coffee shops. To raise sales, it introduced an individual monthly bonus for baristas: a percentage of the add-ons they sell (pastries, extra shots, loyalty sign-ups). The bonus can be 0–35% of monthly pay, and the rules change every quarter. Shift managers decide who works the busy morning shifts, where most sales happen.\n\nSales per customer rose 8%, but customer complaints about \"pushy\" staff doubled, baristas now compete for the till instead of helping each other at the coffee machine, and several say they \"never know what they'll earn.\"", "q": "Using motivation theories, explain the unintended effects of Bean & Co's bonus scheme.", "parts": [["Theory 1: Expectancy theory (Vroom)", "vroom", "Instrumentality is broken: whether effort turns into reward depends on getting morning shifts, which managers allocate. Expectancy is weak because the rules change every quarter. Baristas can't see a reliable link from their effort to their pay."], ["Theory 2: Pay uncertainty (Sayre et al. 2026)", "pfp", "A bonus of 0–35% with changing rules makes income unpredictable: 'never know what they'll earn'. Sayre's experiments show uncertainty causes stress and tunnel vision: staff chase the measured add-ons (pushy upselling) and neglect everything else."], ["Theory 3: Individual vs team pay; output-based pay", "incent", "Individual rewards create competition and withholding of help (Thompson 1995): baristas fight for the till instead of helping at the machine. Paying for output (add-ons) rewards quantity, not quality of service, hence the complaints."], ["Class case", "", "Costco and Target (in Sayre et al.) raised base pay and cut the variable share from about 40% to 20%, keeping motivation while reducing insecurity."], ["Recommendation", "", "Smaller, stable bonus with rules fixed for a year; a shop-level team bonus that includes customer satisfaction; fair, transparent shift rotation. Trade-off: the short-term sales boost may fall."]], "cites": ["sayre"]}, {"id": "atlas", "title": "Atlas Logistics", "tag": "Selection · AI · validity", "pts": 4, "text": "Atlas Logistics hires 3,000 delivery drivers a year across Europe. To speed things up, it introduced an AI video interview: candidates answer five questions on camera, and the software scores their \"communication and confidence\" from facial expressions, voice and word choice. Candidates below a score threshold are rejected automatically.\n\nTime to hire fell from three weeks to four days. But a union complaint shows that candidates with strong accents, a stutter, or who are not native speakers are rejected far more often, even with clean driving records and years of experience. Atlas says the tool is \"neutral because it treats everyone exactly the same.\"", "q": "Assess Atlas's AI selection tool using concepts from class.", "parts": [["Theory 1: Validity and reliability", "relval", "The tool may be reliable (it scores everyone the same way), but it isn't valid for drivers: accent, facial expression and 'confidence on camera' aren't what the job requires. Safe driving, reliability and route skills are. Reliability is necessary but not sufficient for validity, so 'treats everyone the same' doesn't make it fair."], ["Theory 2: AI in recruitment (Tursunbayeva 2024; Session 4)", "ai", "AI should handle mechanical tasks (checking licences, scheduling), not judgments about people, and a human should stay in the loop. Here the AI makes the final rejection automatically, with no audit or explanation, and it discriminates indirectly by disability (stutter) and origin (accent)."], ["Theory 3 (bonus): Signalling and legal criterion", "signal", "Selection methods must also be legal. The union complaint is a legal and reputational risk, and it signals to candidates that Atlas doesn't want them."], ["Class case", "", "Like Amazon's CV tool (2018), which learned to penalise women and was scrapped, and the Aon complaint (2024) on disability and race, Atlas's tool reproduces bias while looking objective."], ["Recommendation", "", "Stop automatic rejection. Use AI only to screen job-relevant facts (licence, record, availability). Add a short practical driving assessment (work sample) and a structured phone interview. Audit outcomes by group. Trade-off: time to hire rises again, so keep AI for scheduling to stay fast."]], "cites": ["ai"]}, {"id": "greenpeak", "title": "GreenPeak", "tag": "Strategic HRM · sustainability · RBV", "pts": 6, "text": "GreenPeak sells outdoor clothing and has built its brand on sustainability: recycled materials, repair services and campaigns about protecting nature. Investors value it highly for its \"purpose-driven\" image.\n\nInside, the picture is different. 70% of store staff are on zero-hour contracts with no guaranteed hours. Training is a two-hour online module. Store staff rarely know how the repair service works or where products come from, and customers notice. Turnover in stores is 80% a year. Head office argues that flexible contracts keep costs low and that \"the brand does the selling.\"", "q": "Is GreenPeak's HR strategy aligned with its business strategy? Discuss and recommend changes.", "parts": [["Theory 1: Strategic HRM and fit", "shrm", "GreenPeak's strategy is differentiation through sustainability and expert service, but its HR treats store staff as a cost to minimise (zero-hour contracts, two-hour training): traditional personnel thinking. That is misaligned: staff who can't explain repairs or sourcing can't deliver the strategy."], ["Theory 2: Resource-based view (VRIO)", "rbv", "Knowledgeable, committed staff who live the brand would be valuable, rare and hard to imitate. A competitor can copy recycled materials, but not a culture. With 80% turnover, GreenPeak throws that resource away and its advantage rests only on marketing, which is easy to copy."], ["Theory 3: Sustainable HRM (Ehnert et al.)", "sust", "A firm that claims social and ecological goals but uses insecure contracts fails the social side of sustainability. Investors and candidates read that gap (signalling), which threatens the purpose-driven image."], ["Class case", "", "Patagonia shows the opposite: HR fully aligned with mission, hiring people who believe in it and offering benefits that match its values."], ["Recommendation", "", "Offer guaranteed-hours contracts for a core store team; real training on products, repair and sourcing; recruit for values and interest in the outdoors; career paths to store expert or manager. Track turnover and customer feedback. Trade-off: higher labour costs, justified by lower turnover and the premium the brand charges."]], "cites": ["patagonia"]}, {"id": "meridian", "title": "Meridian Law", "tag": "Performance · promotion · signalling", "pts": 6, "text": "Meridian is a 400-lawyer firm in London. Last year it launched a \"Respect at Meridian\" programme after several junior lawyers complained about bullying, and introduced 360° feedback for all senior associates.\n\nThis year, Daniel, a senior associate, is up for partner. He billed the most hours in the firm and brought in two major clients. His 360° is split: clients and partners rate him highly, but juniors and support staff rate him 1.8/5 on \"treats colleagues with respect,\" with comments like \"humiliates people in meetings.\" Two juniors in his team asked to be moved. Several partners say: \"He's a rainmaker. If we don't promote him, a rival will.\"", "q": "Should Meridian promote Daniel to partner? Discuss using at least two theories and recommend what the firm should do.", "parts": [["Theory 1: Signalling theory", "signal", "Promotions tell everyone what the firm truly values. Right after launching 'Respect at Meridian', promoting someone rated 1.8/5 on respect would signal that billings excuse bullying, emptying the programme of credibility. Juniors would read it as 'nothing changes'."], ["Theory 2: Performance management criteria and 360°", "pmcrit", "Judging only on hours and clients is deficient: it leaves out leadership and teamwork, which are core for a partner who manages people. The 360° exists to capture exactly that. Ignoring it would also hurt procedural justice: why collect feedback if it doesn't count?"], ["Theory 3: Human capital (portability)", "portab", "The 'rival will take him' fear is partly real: client relationships can move with him. But Groysberg shows stars often perform worse after moving, and some of his success rests on Meridian's platform and team."], ["Class case", "", "This is Rob Parson at Morgan Stanley: a star producer with low teamwork scores in a new 360° system, in a firm trying to change its culture. MDs, like partners, are 'standard bearers' of that culture."], ["Recommendation", "", "Don't promote this year. Give a clear, specific development plan (coaching, behaviour goals measured in next year's 360°) with a real path to partner if it improves, and reward his client work through pay or bonus. Communicate the decision as consistent with the respect programme. Trade-off: he may leave, a risk to weigh against losing juniors and credibility."]], "cites": ["parson"]}, {"id": "helix", "title": "Helix Hospital", "tag": "Wellbeing · stress interventions", "pts": 4, "text": "Helix is a private hospital in Vienna. Nurse sick leave has risen 40% in two years, and a survey shows high exhaustion. Nurses report chronic understaffing, rosters published only a week ahead, frequent double shifts, and little say in how their wards are organised.\n\nHR's response was a wellbeing package: a meditation app, a fruit basket in each ward and a \"resilience\" workshop. Uptake is low, and one nurse wrote: \"I don't need an app, I need a colleague.\"", "q": "Using theories from class, explain why HR's wellbeing package is not working and what Helix should do instead.", "parts": [["Theory 1: Stress interventions (Cooper & Cartwright 1997)", "cooper", "The app, fruit and resilience workshop are secondary interventions: they help people cope with stress but leave the stressors in place. The causes (understaffing, short-notice rosters, double shifts) need primary interventions that change the job itself. 'I need a colleague' says exactly that."], ["Theory 2: Warr's vitamin model", "warr", "Several 'AD vitamins' are out of balance: too little control (no say in how wards run), too little environmental clarity (rosters a week ahead), too much externally imposed demand (double shifts). These cause poor wellbeing regardless of perks."], ["Theory 3: Sustainable HRM and business case", "wb3", "The costs are already visible: sick leave up 40%, and next turnover, errors and patient safety. Sustainable HRM means not burning out the workforce for short-term savings on staff."], ["Class case", "", "Patagonia's early adoption of flexible hours shows wellbeing built into how work is organised, not added on top."], ["Recommendation", "", "Hire or pool extra nurses, publish rosters four or more weeks ahead, limit double shifts, and give nurses a voice in ward planning (self-rostering). Keep the app as a small extra. Trade-off: higher staff costs, offset by less sick leave and agency staffing."]], "cites": ["patagonia"]}], "sessn": {"intro": 1, "brand": 2, "rec": 3, "sel": 4, "comp": 5, "craft": 6, "pm": 7, "well": 8}, "meta": {"title": "HRM exam · Thu 26 Nov, 10:00", "fmtTitle": "The format (90 min, closed book)", "fmtBody": "Part 1: 20 multiple-choice questions (10 pts). Part 2: a short case with Q1 (4 pts) and Q2 (6 pts), max one page each.", "fmtTip": "Timing that works: about 25 min for the MCQs, 25 min for Q1, 35 min for Q2, 5 min to check. In each case answer: name at least two theories, apply them to facts from the case, cite a class case, end with a recommendation.", "paperLabels": {"1": "Paper 1 · the real 2025 exam"}, "ccTip": "Patagonia, L'Oréal, RSH star, Netflix, Name Your Price, Rob Parson…", "note": "The 2025 paper had no answer key. Its answers here are my reading of the slides and readings. Questions in Papers 2–5 and the 3 new cases are written from your materials in the same style.", "back": "HRM exam", "markTitle": "The 4 things markers look for", "markBody": "1. At least two named theories or authors. 2. Applied to facts from this case, not in general. 3. A class case as an example. 4. A clear recommendation or conclusion."}};
var QI = {}; D.qs.forEach(function(q){ QI[q.id] = q; });
var CI = {}; D.cases.forEach(function(c){ CI[c.id] = c; });
var LET = "abcd";
var tick = null, CQ = null;

function H(){ var s = FL.S; if(!s.hr) s.hr = {p:{}, c:{}, log:{}}; ["p","c","log"].forEach(function(k){ if(!s.hr[k]) s.hr[k] = {}; }); return s.hr; }
function P(n){ var h = H(); if(!h.p[n]) h.p[n] = {ans:{}, done:false}; return h.p[n]; }
function C(id){ var h = H(); if(!h.c[id]) h.c[id] = {a:{}, mk:{}, shown:{}}; return h.c[id]; }
function save(){ FL.save(); }
function tname(t){ return D.topics[t] || t; }
function para(s){ return esc(s).split(/\n\n+/).map(function(p){ return "<p>"+p.replace(/\n/g,"<br>")+"</p>"; }).join(""); }
function words(s){ return (String(s||"").trim().match(/\S+/g)||[]).length; }

/* ---------- styles ---------- */
var css = document.createElement("style");
css.textContent = [
".hr .opt{display:flex;gap:10px;align-items:flex-start;text-align:left;font:inherit;width:100%;background:var(--bg);color:var(--ink);border:1px solid var(--line);border-radius:10px;padding:10px 12px;cursor:pointer;margin-top:6px}",
".hr .opt b{min-width:1.2em}",
".hr .opt.sel{border-color:var(--deep);box-shadow:inset 0 0 0 2px var(--deep)}",
".hr .opt.right{background:var(--good-bg);border-color:var(--good)}",
".hr .opt.wrong{background:var(--warn-bg);border-color:var(--warn)}",
".hr .why{font-size:14px;background:var(--bg);border-left:3px solid var(--deep);padding:8px 10px;border-radius:6px}",
".hr .qn{font-size:13px;color:var(--muted);font-weight:600}",
".hr .sticky{position:sticky;top:0;z-index:5;background:var(--bg);padding:8px 0;border-bottom:1px solid var(--line)}",
".hr textarea{min-height:220px;line-height:1.45}",
".hr .ck{display:flex;gap:10px;align-items:flex-start;text-align:left;font:inherit;width:100%;background:transparent;color:var(--ink);border:1px solid var(--line);border-radius:10px;padding:9px 11px;cursor:pointer}",
".hr .ck.on{background:var(--good-bg);border-color:var(--good)}",
".hr .model{white-space:pre-wrap;font-size:14.5px;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:12px}",
".hr .grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px}",
".hr .tile{display:block;text-decoration:none;color:var(--ink);background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:12px}",
".hr .tile small{display:block;color:var(--muted)}",
".hr details{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:10px 12px}",
".hr details summary{cursor:pointer;font-weight:600}",
".hr .th{border-top:1px solid var(--line);padding-top:8px;margin-top:8px;font-size:14.5px}",
".hr .th .use{color:var(--deep);font-weight:600}",
".hr .chips{display:flex;flex-wrap:wrap;gap:6px}",
".hr .chips a{font-size:13px;padding:5px 10px;border:1px solid var(--line);border-radius:999px;text-decoration:none;color:var(--ink);background:var(--surface)}",
".hr .casebox{font-size:15px}",
".hr .casebox p{margin:0 0 10px}",
".hr .big{font-size:28px;font-weight:700}",
".hr .hook{background:var(--warn-bg);border-radius:8px;padding:8px 10px;margin:6px 0}",
".hr .exs{background:var(--good-bg);border-radius:8px;padding:8px 10px;margin:6px 0;font-style:italic}",
".hr .exs b,.hr .hook b{font-style:normal;display:block;font-size:13px}"
].join("\n");
document.head.appendChild(css);

/* ---------- home ---------- */
function paperScore(n){ var p = P(n), ids = D.papers[n], r = 0; ids.forEach(function(id, i){ if(p.ans[i]===QI[id].a) r++; }); return r; }
function caseScore(id){ var c = C(id), cs = CI[id], s = 0, any = false;
  cs.qs.forEach(function(q, i){ var mk = c.mk[i]||{}, n = 0; q.check.forEach(function(_, j){ if(mk[j]) n++; }); if(c.shown[i]) any = true; s += q.pts * n / q.check.length; });
  return any ? Math.round(s*10)/10 : null; }

function vHome(){
  var h = H(), M = D.meta, seen = Object.keys(h.log).length, miss = Object.keys(h.log).filter(function(k){ return h.log[k].miss; }).length;
  var pp = Object.keys(D.papers||{}).map(function(n){
    var p = P(n), cid = D.pcase[n], cs = cid ? caseScore(cid) : null, lab = (M.paperLabels && M.paperLabels[n]) || ("Paper "+n);
    var st = p.done ? '<span class="pill solid">MCQ '+paperScore(n)+'/20</span>' : (Object.keys(p.ans).length ? '<span class="pill prog">MCQ in progress</span>' : '<span class="pill todo">MCQ not started</span>');
    var st2 = cs!==null ? '<span class="pill solid">case ≈ '+cs+'/10</span>' : '';
    return '<div class="card"><div class="row"><b>'+esc(lab)+'</b><span>'+st+' '+st2+'</span></div>'+
      '<div class="grid2"><a class="btn" href="#hr/paper/'+n+'">20 MCQs</a>'+(cid ? '<a class="btn ghost" href="#hr/case/'+cid+'">Case: '+esc(CI[cid].title)+'</a>' : '<a class="btn ghost" href="#hr/cases">Reuse any case</a>')+'</div></div>';
  }).join("");
  if(!pp && M.casePapers){
    pp = D.cases.map(function(c){ var cs = caseScore(c.id), tot = c.qs.reduce(function(a, q){ return a+q.pts; }, 0);
      return '<a class="tile" href="#hr/case/'+c.id+'"><div class="row"><b>'+esc(c.title)+'</b>'+(cs!==null?'<span class="pill solid">≈ '+cs+'/'+tot+'</span>':'<span class="pill todo">'+c.qs.length+' questions · '+tot+' pts</span>')+'</div><small>'+esc(c.src)+'</small></a>'; }).join("");
  }
  var out = '<div class="hr stack"><h1>'+esc(M.title)+'</h1>'+
  '<div class="card"><b>'+esc(M.fmtTitle)+'</b><div>'+esc(M.fmtBody)+'</div><div class="lead">'+esc(M.fmtTip)+'</div></div>';
  if(pp) out += '<h2>Practice papers</h2>'+pp;
  if(D.dr && D.dr.length) out += '<h2>Case drills</h2><a class="tile" href="#hr/drill" style="border-color:var(--deep)"><b>'+D.dr.length+' new cases, answered the exam way</b><small>'+esc(M.drillTip||"Theory applied to case facts, a second theory, a class case, then a recommendation. Write yours, then compare with the answer key.")+'</small></a>';
  if(D.qs && D.qs.length) out += '<h2>Cards</h2><div class="card"><div class="lead">'+D.qs.length+' exam-style questions. '+seen+' seen, '+miss+' to redo.</div>'+
   '<a class="btn" href="#hr/cards/mixed">Mixed cards (10)</a>'+(miss?'<a class="btn ghost" href="#hr/cards/missed">Redo the '+miss+' I got wrong</a>':'')+
   '<div class="chips">'+Object.keys(D.topics).map(function(t){ return '<a href="#hr/cards/'+t+'">'+esc(tname(t))+'</a>'; }).join("")+'</div></div>';
  var side = [];
  if(D.sess && D.sess.length) side.push('<a class="tile" href="#hr/overview"><b>Sessions & theories</b><small>Each session with its theories: a story or memory trick, and an exam sentence</small></a>');
  if(D.coverage) side.push('<a class="tile" href="#hr/coverage"><b>File checklist</b><small>What I extracted from each of your files, and the gaps</small></a>');
  if(D.cc && D.cc.length) side.push('<a class="tile" href="#hr/cases"><b>Class cases</b><small>'+esc(M.ccTip||"")+'</small></a>');
  if(side.length) out += '<h2>On the side</h2><div class="grid2">'+side.join("")+'</div>';
  if(M.note) out += '<p class="lead" style="font-size:13px">'+esc(M.note)+'</p>';
  return out+'</div>';
}

/* ---------- MCQ paper ---------- */
function whyHtml(q, pk){
  if(pk===q.a) return '<div class="why">✓ Right: '+LET[q.a]+'. '+esc(q.w)+'</div>';
  var s = '<div class="why">';
  if(pk<0) s += '<b>Not answered.</b><br>';
  else s += '<b>✗ You picked '+LET[pk]+') '+esc(q.o[pk])+'.</b><br>Why not: '+esc((q.wn && q.wn[pk]) || "it doesn't match the concept the question describes; compare it with the right answer below.")+'<br><br>';
  return s + '<b>Right answer: '+LET[q.a]+') '+esc(q.o[q.a])+'.</b><br>'+esc(q.w)+'</div>';
}
function optBtns(q, picked, reveal, attr){
  return q.o.map(function(o, k){
    var cls = "opt" + (picked===k ? " sel" : "") + (reveal ? (k===q.a ? " right" : (picked===k ? " wrong" : "")) : "");
    return '<button class="'+cls+'" '+(reveal?'disabled ':'')+attr(k)+'><b>'+LET[k]+')</b><span>'+esc(o)+'</span></button>';
  }).join("");
}
function vPaper(n){
  var ids = D.papers[n]; if(!ids) return '<p>No such paper.</p>';
  var p = P(n), got = Object.keys(p.ans).length;
  if(!p.start && !p.done){ p.start = Date.now(); save(); }
  var head = p.done
    ? '<div class="card"><div class="big">'+paperScore(n)+' / 20</div><div class="lead">= '+(paperScore(n)/2)+' of 10 points. Wrong answers are marked; read the why under each one.</div>'+
      '<div class="grid2"><a class="btn" href="'+(D.pcase[n]?'#hr/case/'+D.pcase[n]:'#hr')+'">Now the case</a><button class="btn ghost" data-hr="redo|'+n+'">Redo this paper</button></div></div>'
    : '<div class="sticky row"><span><b>Paper '+n+'</b> · '+got+'/20 answered</span><span class="pill prog" id="hr-clock">25:00</span></div>';
  var body = ids.map(function(id, i){
    var q = QI[id], pk = p.ans[i]; if(pk===undefined) pk = -1;
    return '<div class="card" id="q'+i+'"><div class="qn">'+(i+1)+' · '+esc(tname(q.t))+'</div><div>'+esc(q.q)+'</div>'+
      optBtns(q, pk, p.done, function(k){ return 'data-hr="ans|'+n+'|'+i+'|'+k+'"'; })+
      (p.done ? whyHtml(q, pk) : '')+'</div>';
  }).join("");
  var foot = p.done ? '' : '<button class="btn" data-hr="submit|'+n+'">Hand in and see my score</button>';
  return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><h1>'+(n==="1"?"Paper 1 · 2025 exam":"Paper "+n)+': multiple choice</h1>'+head+body+foot+'</div>';
}

/* ---------- case ---------- */
function vCase(id){
  var cs = CI[id]; if(!cs) return '<p>No such case.</p>';
  var c = C(id);
  var qh = cs.qs.map(function(q, i){
    var txt = c.a[i]||"", shown = c.shown[i], mk = c.mk[i]||{}, n = 0; q.check.forEach(function(_, j){ if(mk[j]) n++; });
    var mins = q.mins || (q.pts===4 ? 25 : 35);
    var s = '<div class="card"><div class="row"><b>Q'+(i+1)+' ('+q.pts+' points)</b><span class="pill prog" id="hr-ct'+i+'">'+mins+' min</span></div><div>'+esc(q.q)+'</div>'+
      '<textarea data-hrta="'+id+'|'+i+'" placeholder="Write as you would on paper: short paragraphs, name the theory, apply it to a case fact, say what it means.">'+esc(txt)+'</textarea>'+
      '<div class="row"><span class="lead" id="hr-wc'+i+'">'+words(txt)+' words (one page ≈ 300–350)</span><button class="btn ghost" style="width:auto" data-hr="ctimer|'+i+'|'+mins+'">Start '+mins+'-min timer</button></div>';
    if(!shown) s += '<button class="btn" data-hr="show|'+id+'|'+i+'">I\'m done: mark my answer</button>';
    else {
      s += '<b>Tick what your answer does</b>'+q.check.map(function(t, j){ return '<button class="ck'+(mk[j]?' on':'')+'" data-hr="mk|'+id+'|'+i+'|'+j+'"><span>'+(mk[j]?'☑':'☐')+'</span><span>'+esc(t)+'</span></button>'; }).join("")+
        '<div class="row"><span>Rough score</span><b>'+(Math.round(q.pts*n/q.check.length*10)/10)+' / '+q.pts+'</b></div>'+
        '<details><summary>Model answer</summary><div class="model">'+esc(q.model)+'</div></details>';
    }
    return s+'</div>';
  }).join("");
  return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><h1>Case: '+esc(cs.title)+'</h1><div class="lead">'+esc(cs.src)+'</div>'+
    (cs.doc ? '<a class="btn" href="#doc/'+cs.doc+'/1">Open the exam paper (full case and exhibits)</a>' : '')+'<details open><summary>'+(cs.doc?'The case in brief':'The case')+'</summary><div class="casebox">'+para(cs.text)+'</div></details>'+qh+
    '<div class="card"><b>'+esc(D.meta.markTitle)+'</b><div>'+esc(D.meta.markBody)+'</div></div></div>';
}

/* ---------- cards ---------- */
function pool(sel){
  var h = H();
  if(sel==="missed") return D.qs.filter(function(q){ return h.log[q.id] && h.log[q.id].miss; });
  return D.qs.filter(function(q){ return sel==="mixed" || q.t===sel; });
}
function newRound(sel){
  var h = H(), ps = pool(sel).slice();
  ps.forEach(function(q){ var l = h.log[q.id]; q._k = (l ? (l.miss ? 1 : 2) : 0) + Math.random(); });
  ps.sort(function(a, b){ return a._k - b._k; });
  CQ = {sel:sel, items:ps.slice(0, 10), i:0, picked:-1, right:0};
}
function vCards(sel){
  if(!CQ || CQ.sel!==sel) newRound(sel);
  var chips = '<div class="chips"><a href="#hr/cards/mixed">Mixed</a>'+Object.keys(D.topics).map(function(t){ return '<a href="#hr/cards/'+t+'">'+esc(tname(t))+'</a>'; }).join("")+'</div>';
  var title = sel==="mixed" ? "Mixed cards" : sel==="missed" ? "Cards I got wrong" : tname(sel);
  if(!CQ.items.length) return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><h1>'+esc(title)+'</h1><p>Nothing here right now.</p>'+chips+'</div>';
  if(CQ.i >= CQ.items.length){
    return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><h1>'+esc(title)+'</h1><div class="card"><div class="big">'+CQ.right+' / '+CQ.items.length+'</div>'+
      '<button class="btn" data-hr="more">Keep going: 10 more</button></div>'+chips+'</div>';
  }
  var q = CQ.items[CQ.i], done = CQ.picked>=0;
  return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><div class="row"><h1 style="margin:0">'+esc(title)+'</h1><span class="pill prog">'+(CQ.i+1)+' / '+CQ.items.length+'</span></div>'+
    '<div class="card"><div class="qn">'+esc(tname(q.t))+(q.src?' · '+esc(q.src):'')+'</div><div>'+esc(q.q)+'</div>'+
    optBtns(q, CQ.picked, done, function(k){ return 'data-hr="pick|'+k+'"'; })+
    (done ? whyHtml(q, CQ.picked)+'<button class="btn" data-hr="next">Next</button>' : '')+'</div>'+chips+'</div>';
}

/* ---------- overview ---------- */
function thHtml(k){ var t = D.th[k]; if(!t) return "";
  var st = String(t.story||""), lab = /^Story:/.test(st) ? "📖 The story" : "🧠 Memory trick"; st = st.replace(/^(Story|Trick):\s*/,"");
  return '<div class="th"><b>'+esc(t.n)+'</b> <span class="lead">('+esc(t.who)+')</span>'+
    (st ? '<div class="hook"><b>'+lab+'</b><div>'+esc(st)+'</div></div>' : '')+
    '<div><b>What it says: </b>'+esc(t.what)+'</div>'+
    (t.ex ? '<div class="exs"><b>✍️ Exam sentence</b><div>'+esc(t.ex)+'</div></div>' : '<div><span class="use">In a case answer: </span>'+esc(t.use)+'</div>')+'</div>'; }
function vOverview(){
  return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><h1>Sessions & theories</h1>'+
    '<p class="lead">Tap a session. Each theory says what it is and how to use it in a case answer.</p>'+
    D.sess.map(function(s){
      return '<details><summary>S'+s.n+' · '+esc(s.title)+'</summary><div class="stack" style="margin-top:8px">'+
        '<div><b>Key question:</b> '+esc(s.q)+'</div><div><b>Class case:</b> '+esc(s.case)+'</div><div><b>Reading:</b> '+esc(s.read)+'</div>'+
        s.theory.map(thHtml).join("")+'<a class="btn ghost" href="#hr/cards/'+s.t+'">Cards for this session</a></div></details>';
    }).join("")+'</div>';
}
function vClassCases(){
  return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><h1>Class cases</h1>'+
    '<p class="lead">Tap a case: the idea, the problem, what they did, whether it worked and why, the lessons, and the theories behind it.</p>'+
    D.cc.map(function(c){ return '<a class="tile" href="#hr/cc/'+c.id+'"><div class="row"><b>'+esc(c.name)+'</b><span class="pill todo">'+esc(c.sess.split(" · ")[0])+'</span></div><small>'+esc(c.idea)+'</small></a>'; }).join("")+'</div>';
}
function vCC(id){
  var i = -1; D.cc.forEach(function(c, k){ if(c.id===id) i = k; }); if(i<0) return vClassCases();
  var c = D.cc[i], pv = D.cc[i-1], nx = D.cc[i+1];
  function sec(t, body){ return '<div class="card"><b>'+t+'</b><div>'+body+'</div></div>'; }
  return '<div class="hr stack"><a href="#hr/cases" class="lead">‹ All class cases</a><h1>'+esc(c.name)+'</h1><div class="lead">'+esc(c.sess)+'</div>'+
    sec("The idea in one line", esc(c.idea))+
    sec("The main problem", esc(c.problem))+
    sec("What they did (the plan)", esc(c.plan))+
    sec("Did it work? Why or why not", esc(c.result))+
    sec("Lessons learnt", '<ul style="margin:0;padding-left:20px">'+c.lessons.map(function(l){ return '<li>'+esc(l)+'</li>'; }).join("")+'</ul>')+
    '<div class="card"><b>The theories behind it</b>'+c.th.map(thHtml).join("")+'</div>'+
    '<div class="card" style="border-color:var(--deep)"><b>One sentence for your exam answer</b><div class="why">'+esc(c.line)+'</div><div class="lead" style="font-size:13px">Swap X for the company in the exam case.</div></div>'+
    '<div class="grid2">'+(pv?'<a class="btn ghost" href="#hr/cc/'+pv.id+'">‹ '+esc(pv.name)+'</a>':'<span></span>')+(nx?'<a class="btn ghost" href="#hr/cc/'+nx.id+'">'+esc(nx.name)+' ›</a>':'')+'</div></div>';
}

/* ---------- case drills: the answer formula ---------- */
var STARTERS = [["Theory 1","According to [theory, author], … In this case, [fact from the case] shows … This leads to …"],["Theory 2","A second lens is [theory, author]: … Here, [another fact] means …"],["Class case","This is similar to [class case], where … "],["Recommendation","Therefore X should (1) …, (2) …, (3) … This would …, although [trade-off]."]];
function DD(id){ var h = H(); if(!h.d) h.d = {}; if(!h.d[id]) h.d[id] = {a:"", rv:0, ok:{}}; return h.d[id]; }
function vDrills(){
  var h = H();
  return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><h1>Case drills</h1>'+
    '<div class="card"><b>The formula for every case answer</b><div>1. Name a theory and apply it to facts from the case.<br>2. Name a second theory and apply it too.<br>3. Cite a class case.<br>4. End with a recommendation.</div><div class="lead">Each drill is a short case. Write your answer, then reveal the model answer one part at a time and compare.</div></div>'+
    D.dr.map(function(x){ var st = h.d && h.d[x.id], done = st && st.rv>=4;
      return '<a class="tile" href="#hr/drill/'+x.id+'"><div class="row"><b>'+esc(x.title)+'</b><span class="pill '+(done?'solid':'todo')+'">'+(done?'done':esc(tname(x.t)).split(" ")[0])+'</span></div><small>'+esc(x.q)+'</small></a>'; }).join("")+'</div>';
}
function vDrill(id){
  var i = -1; D.dr.forEach(function(x, k){ if(x.id===id) i = k; }); if(i<0) return vDrills();
  var x = D.dr[i], st = DD(id), nx = D.dr[i+1];
  var parts = x.parts.map(function(p, k){
    if(k >= st.rv) return '';
    return '<div class="card"><div class="row"><b>'+(k+1)+'. '+esc(p[0])+'</b><button class="ck'+(st.ok[k]?' on':'')+'" style="width:auto" data-hr="dok|'+id+'|'+k+'">'+(st.ok[k]?'☑ I had this':'☐ I had this')+'</button></div><div class="why" style="font-size:15px">'+esc(p[1])+'</div></div>';
  }).join("");
  var nOk = Object.keys(st.ok).filter(function(k){ return st.ok[k]; }).length;
  return '<div class="hr stack"><a href="#hr/drill" class="lead">‹ All case drills</a><h1>'+esc(x.title)+'</h1><div class="lead">'+esc(tname(x.t))+'</div>'+
    '<div class="card casebox">'+para(x.text)+'</div>'+
    '<div class="card"><b>Question</b><div>'+esc(x.q)+'</div>'+
    '<details><summary>Sentence starters (if you\'re stuck)</summary>'+STARTERS.map(function(s){ return '<div class="th"><b>'+s[0]+'</b><div>'+esc(s[1])+'</div></div>'; }).join("")+'</details>'+
    '<textarea data-hrdr="'+id+'" placeholder="Theory 1 + case facts… Theory 2 + case facts… Class case… Recommendation…">'+esc(st.a)+'</textarea>'+
    '<div class="lead" id="hr-dwc">'+words(st.a)+' words</div></div>'+
    parts+
    (st.rv<4 ? '<div class="grid2"><button class="btn" data-hr="drv|'+id+'">Reveal '+(st.rv===0?'part 1':'next part')+'</button><button class="btn ghost" data-hr="dall|'+id+'">Show all</button></div>'
             : '<div class="card"><div class="row"><b>You had</b><b>'+nOk+' / 4 parts</b></div>'+(nx?'<a class="btn" href="#hr/drill/'+nx.id+'">Next drill: '+esc(nx.title)+'</a>':'<a class="btn" href="#hr/drill">Back to all drills</a>')+'<button class="btn ghost" data-hr="dreset|'+id+'">Hide answer and try again</button></div>')+
  '</div>';
}

/* ---------- case drills ---------- */
var SKEL = (D.meta && D.meta.skel) || "Theory 1 (name + author):\nApplied to the case:\n\nTheory 2 (name + author):\nApplied to the case:\n\nClass case:\n\nRecommendation (+ trade-off):\n";
function Dd(id){ var h = H(); if(!h.d) h.d = {}; if(!h.d[id]) h.d[id] = {a:"", shown:false, mk:{}}; return h.d[id]; }
var DCK = (D.meta && D.meta.dck) || ["Named at least 2 theories with authors","Applied each theory to specific facts from this case (numbers, quotes, events)","Cited a class case and said why it's similar","Ended with a concrete recommendation (and a trade-off)"];
function vDrills(){
  return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><h1>Case drills</h1>'+
    '<div class="card"><b>The answer pattern, every time</b><div>1. Name a theory (and author). 2. Apply it to facts from the case. 3. Repeat with a second theory. 4. Cite a class case. 5. Recommendation with a trade-off.</div><div class="lead">New cases you haven\'t seen in class. The answer key uses only theories from your course.</div></div>'+
    D.dr.map(function(d){ var x = Dd(d.id), st = x.shown ? '<span class="pill solid">done</span>' : (x.a ? '<span class="pill prog">started</span>' : '<span class="pill todo">'+d.pts+' pts</span>');
      return '<a class="tile" href="#hr/drill/'+d.id+'"><div class="row"><b>'+esc(d.title)+'</b>'+st+'</div><small>'+esc(d.tag)+'</small></a>'; }).join("")+'</div>';
}
function vDrill(id){
  var i = -1; D.dr.forEach(function(d, k){ if(d.id===id) i = k; }); if(i<0) return vDrills();
  var d = D.dr[i], x = Dd(id), nx = D.dr[i+1], mins = d.pts===4 ? 25 : 35, n = 0; DCK.forEach(function(_, j){ if(x.mk[j]) n++; });
  var s = '<div class="hr stack"><a href="#hr/drill" class="lead">‹ All case drills</a><h1>'+esc(d.title)+'</h1><div class="lead">'+esc(d.tag)+'</div>'+
    '<details open><summary>The case</summary><div class="casebox">'+para(d.text)+'</div></details>'+
    '<div class="card"><div class="row"><b>Question ('+d.pts+' points)</b><span class="pill prog" id="hr-ct0">'+mins+' min</span></div><div>'+esc(d.q)+'</div>'+
    '<textarea data-hrdr="'+id+'" placeholder="Tap \'Insert the 4-part skeleton\' to start.">'+esc(x.a)+'</textarea>'+
    '<div class="row"><span class="lead" id="hr-wc0">'+words(x.a)+' words</span></div>'+
    '<div class="grid2"><button class="btn ghost" data-hr="skel|'+id+'">Insert the 4-part skeleton</button><button class="btn ghost" data-hr="ctimer|0|'+mins+'">Start '+mins+'-min timer</button></div>';
  if(!x.shown) s += '<button class="btn" data-hr="dshow|'+id+'">I\'m done: show the answer key</button></div>';
  else {
    s += '<b>Tick what your answer does</b>'+DCK.map(function(t, j){ return '<button class="ck'+(x.mk[j]?' on':'')+'" data-hr="dmk|'+id+'|'+j+'"><span>'+(x.mk[j]?'☑':'☐')+'</span><span>'+esc(t)+'</span></button>'; }).join("")+
      '<div class="row"><span>Rough score</span><b>'+(Math.round(d.pts*n/4*10)/10)+' / '+d.pts+'</b></div></div>'+
      '<h2>Answer key</h2>'+d.parts.map(function(p){
        var kind = /^Theory/.test(p[0]) ? "var(--deep)" : /^Class/.test(p[0]) ? "var(--info)" : "var(--accent)";
        return '<div class="card" style="border-left:4px solid '+kind+'"><b>'+esc(p[0])+'</b><div>'+esc(p[2])+'</div>'+(p[1] && D.th[p[1]] ? '<details><summary>Theory card</summary>'+thHtml(p[1])+'</details>' : '')+'</div>';
      }).join("")+
      (d.cites||[]).map(function(c){ return '<a class="btn ghost" href="#hr/cc/'+c+'">Open the class case page: '+esc((D.cc.filter(function(z){ return z.id===c; })[0]||{}).name||c)+'</a>'; }).join("");
  }
  s += (nx ? '<a class="btn" href="#hr/drill/'+nx.id+'">Next drill: '+esc(nx.title)+' ›</a>' : '<a class="btn" href="#hr/drill">All drills</a>')+'</div>';
  return s;
}

function vCoverage(){
  return '<div class="hr stack"><a href="#hr" class="lead">‹ '+esc(D.meta.back||"Exam home")+'</a><h1>What I extracted from each file</h1>'+
    '<p class="lead">Every file you sent, and what it became in the app. Gaps are marked.</p>'+
    D.coverage.map(function(c){ return '<div class="card"><div class="row"><b>'+esc(c[0])+'</b>'+(c[2]?'<span class="pill todo">gap</span>':'<span class="pill solid">used</span>')+'</div><div>'+esc(c[1])+'</div></div>'; }).join("")+'</div>';
}

/* ---------- router ---------- */
function view(r){
  if(tick){ clearInterval(tick); tick = null; }
  var m;
  if((m = r.match(/^hr\/paper\/(\d)$/))) return vPaper(m[1]);
  if((m = r.match(/^hr\/case\/([a-z]+)$/))) return vCase(m[1]);
  if((m = r.match(/^hr\/cards\/([a-z]+)$/))) return vCards(m[1]);
  if(r==="hr/overview") return vOverview();
  if(r==="hr/cases") return vClassCases();
  if(r==="hr/coverage" && D.coverage) return vCoverage();
  if(r==="hr/drill") return vDrills();
  if((m = r.match(/^hr\/drill\/([a-z]+)$/))) return vDrill(m[1]);
  if(r==="hr/drill") return vDrills();
  if((m = r.match(/^hr\/drill\/([a-z0-9]+)$/))) return vDrill(m[1]);
  if((m = r.match(/^hr\/cc\/([a-z]+)$/))) return vCC(m[1]);
  return vHome();
}
var ctimer = null;
function after(r){
  var m = r.match(/^hr\/paper\/(\d)$/);
  if(m && !P(m[1]).done){
    var p = P(m[1]);
    var up = function(){ var el = document.getElementById("hr-clock"); if(!el) return; var l = 25*60 - Math.floor((Date.now()-(p.start||Date.now()))/1000);
      el.textContent = l>=0 ? Math.floor(l/60)+":"+("0"+l%60).slice(-2) : "+"+Math.floor(-l/60)+" min over"; };
    up(); tick = setInterval(up, 1000);
  }
  if(/^hr\/(case|drill)\//.test(r) && ctimer){
    var upc = function(){ var el = document.getElementById("hr-ct"+ctimer.i); if(!el) return; var l = ctimer.secs - Math.floor((Date.now()-ctimer.start)/1000);
      el.textContent = l>=0 ? Math.floor(l/60)+":"+("0"+l%60).slice(-2) : "time's up"; };
    upc(); tick = setInterval(upc, 1000);
  }
}

/* ---------- events ---------- */
var app = document.getElementById("app");
app.addEventListener("click", function(e){
  var b = e.target.closest("[data-hr]"); if(!b) return;
  e.stopPropagation();
  var a = b.dataset.hr.split("|"), y = window.scrollY;
  if(a[0]==="ans"){ var p = P(a[1]); if(p.done) return; p.ans[+a[2]] = +a[3]; save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="submit"){ var p2 = P(a[1]), ids = D.papers[a[1]], h = H();
    ids.forEach(function(id, i){ h.log[id] = {t:Date.now(), miss:p2.ans[i]!==QI[id].a}; });
    p2.done = true; p2.at = Date.now(); save(); FL.render(); window.scrollTo(0,0); if(paperScore(a[1])>=16 && FL.confetti) FL.confetti(); return; }
  if(a[0]==="redo"){ H().p[a[1]] = {ans:{}, done:false}; save(); FL.render(); window.scrollTo(0,0); return; }
  if(a[0]==="show"){ C(a[1]).shown[+a[2]] = true; save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="mk"){ var c = C(a[1]), mk = c.mk[+a[2]] = c.mk[+a[2]] || {}; mk[+a[3]] = !mk[+a[3]]; save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="ctimer"){ ctimer = {i:+a[1], secs:(+a[2])*60, start:Date.now()}; FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="drv"){ var dd = DD(a[1]); dd.rv = Math.min(4, dd.rv+1); save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="dall"){ DD(a[1]).rv = 4; save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="dreset"){ var d2 = DD(a[1]); d2.rv = 0; d2.ok = {}; save(); FL.render(); window.scrollTo(0,0); return; }
  if(a[0]==="dok"){ var d3 = DD(a[1]); d3.ok[+a[2]] = !d3.ok[+a[2]]; save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="skel"){ var dd = Dd(a[1]); if(!dd.a.trim()) dd.a = SKEL; else if(dd.a.indexOf("Theory 1")<0) dd.a = SKEL+"\n"+dd.a; save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="dshow"){ Dd(a[1]).shown = true; save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="dmk"){ var dm = Dd(a[1]).mk; dm[+a[2]] = !dm[+a[2]]; save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="pick" && CQ){ if(CQ.picked>=0) return; var q = CQ.items[CQ.i]; CQ.picked = +a[1]; var ok = CQ.picked===q.a; if(ok) CQ.right++;
    H().log[q.id] = {t:Date.now(), miss:!ok}; save(); FL.render(); window.scrollTo(0, y); return; }
  if(a[0]==="next" && CQ){ CQ.i++; CQ.picked = -1; FL.render(); window.scrollTo(0,0); return; }
  if(a[0]==="more" && CQ){ newRound(CQ.sel); FL.render(); window.scrollTo(0,0); return; }
}, true);
var tmo = null;
app.addEventListener("input", function(e){
  var t = e.target; if(!t.dataset) return;
  if(t.dataset.hrdr){ DD(t.dataset.hrdr).a = t.value; var dw = document.getElementById("hr-dwc"); if(dw) dw.textContent = words(t.value)+" words"; clearTimeout(tmo); tmo = setTimeout(save, 800); return; }
  if(!t.dataset.hrta) return;
  var a = t.dataset.hrta.split("|"); C(a[0]).a[+a[1]] = t.value;
  var wc = document.getElementById("hr-wc"+a[1]); if(wc) wc.textContent = words(t.value)+" words (one page ≈ 300–350)";
  clearTimeout(tmo); tmo = setTimeout(save, 800);
});

window.FLHR = {view:view, after:after};
window.FLC = window.FLC || {}; window.FLC.hr = {view:view, after:after, meta:D.meta};
if(/^#?hr/.test(location.hash||"") || !location.hash) FL.render();
})();
